@dataclass
class PanelRun:
    """Estado independente de uma execução de painel."""
    panel: str
    stop_event: threading.Event = field(default_factory=threading.Event)
    total_steps: int = 0
    run_id: str = field(default_factory=lambda: uuid.uuid4().hex)
    active_processes: set[object] = field(default_factory=set, repr=False)
    process_lock: threading.Lock = field(default_factory=threading.Lock, repr=False)

    def stop_now(self) -> None:
        """Cancela ADBs em curso, além de sinalizar a lógica da execução."""
        self.stop_event.set()
        with self.process_lock:
            processes = tuple(self.active_processes)
        for process in processes:
            try:
                if process.poll() is None:
                    process.terminate()
            except (AttributeError, OSError):
                pass


@dataclass(frozen=True)
class PanelEvent:
    panel: str
    payload: object
    # A mesma execução pode ter mais de um telefone. Guardar o serial junto
    # do evento permite que a grade mostre um log realmente próprio de cada
    # aparelho, sem misturar mensagens de outros cartões.
    serial: str | None = None


class PanelEventQueue:
    """Anexa o painel aos eventos enviados pelas threads de execução.

    Assim a interface pode continuar com uma só fila Tk, porém log, progresso e
    destaque de cada painel nunca se misturam.
    """
    def __init__(self, context: threading.local):
        self._queue: queue.Queue[tuple[str, object]] = queue.Queue()
        self._context = context

    def put(self, value: tuple[str, object], *args, **kwargs) -> None:
        panel = getattr(self._context, "panel", None)
        if panel:
            kind, payload = value
            serial = getattr(self._context, "serial", None)
            value = (kind, PanelEvent(str(panel), payload, str(serial) if serial else None))
        self._queue.put(value, *args, **kwargs)

    def get_nowait(self):
        return self._queue.get_nowait()


class PanelStopProxy:
    """Mantém o código de execução existente usando um evento por painel."""
    def __init__(self, context: threading.local, fallback: threading.Event):
        self._context = context
        self._fallback = fallback

    def _event(self) -> threading.Event:
        run = getattr(self._context, "run", None)
        return run.stop_event if run is not None else self._fallback

    def is_set(self) -> bool:
        return self._event().is_set()

    def wait(self, timeout: float | None = None) -> bool:
        return self._event().wait(timeout)

    def set(self) -> None:
        self._event().set()

    def clear(self) -> None:
        self._event().clear()


