class Adb:
    def __init__(self) -> None:
        self.serial: str | None = None
        bundled = ADB_DIR / "adb.exe"
        self.path = str(bundled) if bundled.exists() else (shutil.which("adb") or "adb")

    def command(self, *args: str, timeout: float = 15) -> str:
        base = [self.path]
        if self.serial:
            base += ["-s", self.serial]
        panel_run = getattr(ADB_PROCESS_CONTEXT, "run", None)
        if panel_run and panel_run.stop_event.is_set():
            raise InterruptedError("Execução interrompida")
        process = subprocess.Popen(base + list(args), stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
                                   encoding="utf-8", errors="replace", creationflags=NO_CONSOLE)
        if panel_run:
            with panel_run.process_lock:
                panel_run.active_processes.add(process)
        try:
            stdout, stderr = process.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            process.kill()
            stdout, stderr = process.communicate()
            raise
        finally:
            if panel_run:
                with panel_run.process_lock:
                    panel_run.active_processes.discard(process)
        if process.returncode:
            detail = stderr.strip() or stdout.strip() or "sem detalhe retornado pelo aparelho"
            raise RuntimeError(f"ADB falhou em {' '.join(args[:3])}: {detail}")
        return stdout

    def devices(self) -> list[tuple[str, str]]:
        # `adb devices` precisa funcionar mesmo se o último aparelho escolhido
        # já foi desconectado; por isso nunca recebe o argumento `-s`.
        run = subprocess.run([self.path, "devices"], capture_output=True, text=True,
                             encoding="utf-8", errors="replace", timeout=12,
                             creationflags=NO_CONSOLE)
        if run.returncode:
            raise RuntimeError(run.stderr.strip() or run.stdout.strip() or "ADB falhou")
        out = run.stdout
        return [tuple(line.split(maxsplit=1)) for line in out.splitlines()[1:]
                if "\t" in line]

    def launch_package(self, package: str, timeout: float = 20) -> None:
        """Abre um app pelo launcher, inclusive em Androids com launcher customizado."""
        try:
            resolved = self.command(
                "shell", "cmd", "package", "resolve-activity", "--brief",
                "-a", "android.intent.action.MAIN",
                "-c", "android.intent.category.LAUNCHER",
                package,
                timeout=timeout,
            )
        except RuntimeError:
            resolved = ""
        component = next((line.strip() for line in resolved.splitlines()
                          if line.strip().startswith(package + "/")), "")
        if component:
            output = self.command("shell", "am", "start", "-W", "-n", component, timeout=timeout)
            if not re.search(r"\b(error|unable to resolve|does not exist)\b", output, re.IGNORECASE):
                return
        # Alguns firmwares não retornam o componente no resolve-activity,
        # embora aceitem o intent padrão. Esta segunda tentativa evita que a
        # etapa pare indevidamente em aparelhos com launcher customizado.
        output = self.command("shell", "am", "start", "-W",
                              "-a", "android.intent.action.MAIN",
                              "-c", "android.intent.category.LAUNCHER",
                              "-p", package, timeout=timeout)
        if re.search(r"\b(error|unable to resolve|does not exist)\b", output, re.IGNORECASE):
            detail = output.strip() or "sem tela inicial compatível"
            raise RuntimeError(f"Não foi possível abrir {package}: {detail}")

    def is_screen_locked(self) -> bool:
        """Detecta a tela de bloqueio sem tentar contornar credenciais."""
        window_state = self.command("shell", "dumpsys", "window", timeout=15).casefold()
        policy_state = self.command("shell", "dumpsys", "window", "policy", timeout=15).casefold()
        markers = ("mshowinglockscreen=true", "mdreaminglockscreen=true", "keyguardshowing=true", "showing keyguard: true")
        return any(marker in window_state or marker in policy_state for marker in markers)

    def device_label(self, serial: str) -> str:
        """Retorna uma identificação legível sem alterar o aparelho selecionado."""
        old_serial = self.serial
        try:
            self.serial = serial
            manufacturer = self.command("shell", "getprop", "ro.product.manufacturer").strip()
            model = self.command("shell", "getprop", "ro.product.model").strip()
            return " ".join(part for part in (manufacturer, model) if part) or "Modelo não informado"
        finally:
            self.serial = old_serial

    def screen_size(self, timeout: float = 15) -> tuple[int, int]:
        out = self.command("shell", "wm", "size", timeout=timeout)
        # `wm size` pode listar primeiro a tela física e depois uma resolução
        # "override". O `adb shell input` e a captura de tela usam a escala
        # física neste caso; escolher a última fazia a prévia (e novas
        # gravações) deslocarem progressivamente os toques.
        physical = re.search(r"Physical size:\s*(\d+)x(\d+)", out, re.IGNORECASE)
        if physical:
            return int(physical.group(1)), int(physical.group(2))
        found = re.findall(r"(\d+)x(\d+)", out)
        if not found:
            raise RuntimeError("Não consegui identificar o tamanho da tela.")
        return tuple(map(int, found[0]))

    def is_package_foreground(self, package: str) -> bool:
        """Confirma se ``package`` é o aplicativo que está em primeiro plano."""
        # `mCurrentFocus` identifica a janela realmente visível. Não basta a
        # atividade retomada: após um crash ela pode continuar listada por
        # alguns instantes, embora a tela do Instagram já tenha desaparecido.
        window = self.command("shell", "dumpsys", "window", "windows", timeout=10)
        focus_lines = [
            line for line in window.splitlines()
            if re.search(r"mCurrentFocus", line, re.IGNORECASE)
        ]
        if not focus_lines:
            # Compatibilidade com aparelhos que não expõem mCurrentFocus.
            activity = self.command("shell", "dumpsys", "activity", "activities", timeout=10)
            focus_lines = [
                line for line in activity.splitlines()
                if re.search(r"topResumedActivity|mResumedActivity", line, re.IGNORECASE)
            ]
        return any(re.search(rf"(?<![\w.]){re.escape(package)}(?:/|\b)", line) for line in focus_lines)

    def touch_range(self, fallback: tuple[int, int]) -> tuple[int, int]:
        """Lê a escala do touchscreen, quando o fabricante a expõe ao ADB."""
        out = self.command("shell", "getevent", "-lp")
        maximums: dict[str, int] = {}
        for line in out.splitlines():
            for axis in ("ABS_MT_POSITION_X", "ABS_MT_POSITION_Y", "ABS_X", "ABS_Y"):
                if axis in line:
                    found = re.search(r"\bmax\s+(-?\d+)", line)
                    if found:
                        maximums[axis] = int(found.group(1)) + 1
        x = maximums.get("ABS_MT_POSITION_X", maximums.get("ABS_X", fallback[0]))
        y = maximums.get("ABS_MT_POSITION_Y", maximums.get("ABS_Y", fallback[1]))
        return x, y

    def _recover_uiautomator(self, use_root: bool = False) -> None:
        """Encerra um dump preso e só prossegue após ele realmente sair.

        O comando anterior dependia de ``pkill``/``awk`` existirem em todos os
        aparelhos. Em alguns Samsung eles falham silenciosamente; a tentativa
        seguinte então cria outro dump enquanto o anterior ainda ocupa o canal
        de acessibilidade.
        """
        pids: list[str] = []
        # Sem serial (caso de teste/local), preserva a limpeza genérica abaixo.
        # Na execução real sempre há serial e usamos o PID exato do aparelho.
        if self.serial:
            try:
                pids = self.command("shell", "pidof", "uiautomator", timeout=3).split()
            except (OSError, subprocess.SubprocessError, RuntimeError):
                pids = []
        if pids:
            try:
                self.command("shell", "kill", "-9", *pids, timeout=3)
            except (OSError, subprocess.SubprocessError, RuntimeError):
                pass
            # ``kill`` é assíncrono no Android. Esperar a saída evita iniciar
            # uma nova instância enquanto a anterior ainda está em futex.
            for _ in range(12):
                time.sleep(0.10)
                try:
                    if not self.command("shell", "pidof", "uiautomator", timeout=2).strip():
                        break
                except (OSError, subprocess.SubprocessError, RuntimeError):
                    break
        cleanup = (
            "rm -f /sdcard/iggent_ui_0.xml /sdcard/iggent_ui_1.xml /sdcard/macro_window.xml; "
            "am force-stop com.android.uiautomator 2>/dev/null || true; "
            "cmd activity force-stop com.android.uiautomator 2>/dev/null || true; "
            "(toybox pkill -9 -f uiautomator || pkill -9 -f uiautomator || "
            "killall -9 uiautomator || true) >/dev/null 2>&1; "
            "for pid in $(ps -A 2>/dev/null | grep '[u]iautomator' | awk '{print $2}'; "
            "ps -ef 2>/dev/null | grep '[u]iautomator' | awk '{print $2}'); "
            "do kill -9 $pid 2>/dev/null; done"
        )
        try:
            self.command("shell", cleanup, timeout=4)
        except (OSError, subprocess.SubprocessError, RuntimeError):
            pass
        # Em aparelhos com root, há casos em que o processo não pertence mais
        # ao usuário shell. A última tentativa do lote também o remove como
        # root, mas falhar nisso nunca impede as tentativas normais.
        if use_root:
            try:
                self.command("shell", f"su -c {shlex.quote(cleanup)}", timeout=5)
            except (OSError, subprocess.SubprocessError, RuntimeError):
                pass
        # Dá ao AccessibilityManager um ciclo para liberar o canal após o
        # processo Java morrer. Sem este intervalo, o próximo dump reaparece
        # imediatamente em estado travado em alguns Android 15.
        time.sleep(0.25)

    def ui_xml(self, timeout: float = 12, force_root_recovery: bool = False) -> str:
        """Serializa dumps do mesmo telefone antes de acessar uiautomator."""
        key = str(self.serial or "__default__")
        with _UI_XML_LOCKS_GUARD:
            lock = _UI_XML_LOCKS.setdefault(key, threading.Lock())
        wait_s = max(20.0, float(timeout) * 4)
        if not lock.acquire(timeout=wait_s):
            raise RuntimeError("Outra captura XML deste telefone ainda está em andamento")
        try:
            return self._ui_xml_locked(timeout=timeout, force_root_recovery=force_root_recovery)
        finally:
            lock.release()

    def _ui_xml_locked(self, timeout: float = 12, force_root_recovery: bool = False) -> str:
        """Captura o XML com recuperação de falhas transitórias do uiautomator."""
        last_error: Exception | None = None
        attempts = 2
        # Em telas grandes, especialmente depois de reconectar o aparelho, o
        # primeiro dump pode levar mais de 3.5 s. Cortá-lo cedo e matá-lo
        # criava um ciclo infinito de processos presos. A recuperação abaixo
        # ainda protege a execução, mas primeiro deixa uma captura legítima
        # concluir.
        per_attempt = max(6.0, min(float(timeout), 9.0))

        def valid_xml(output: str) -> str:
            """Remove mensagens auxiliares que alguns Androids põem no dump."""
            start = output.find("<?xml")
            if start < 0:
                start = output.find("<hierarchy")
            candidate = output[start:] if start >= 0 else ""
            return candidate if "<hierarchy" in candidate else ""

        for attempt in range(attempts):
            # Alternar o arquivo e apagá-lo antes do dump impede reutilizar um
            # XML antigo depois de um encerramento inesperado do Android.
            path = f"/sdcard/iggent_ui_{attempt % 2}.xml"
            compressed = " --compressed" if attempt else ""
            command = f"rm -f {path}; uiautomator dump{compressed} {path} >/dev/null && cat {path}"
            try:
                xml = self.command("shell", command, timeout=per_attempt)
                xml = valid_xml(xml)
                if xml:
                    return xml
                last_error = RuntimeError("uiautomator não retornou um XML válido")
            except (OSError, subprocess.SubprocessError, RuntimeError) as error:
                last_error = error
            if attempt < attempts - 1:
                time.sleep(0.45)
        # Só depois de duas tentativas genuínas fazemos a limpeza. Isso evita
        # matar o próprio uiautomator enquanto ele ainda inicializa.
        self._recover_uiautomator(use_root=force_root_recovery)
        # Em alguns fabricantes o dump trava ao escrever no armazenamento do
        # aparelho. Esta rota lê diretamente pela saída do ADB, sem criar nem
        # copiar XML no telefone, portanto independe do caminho que travou.
        try:
            direct = self.command(
                "exec-out", "uiautomator", "dump", "--compressed", "/dev/tty",
                timeout=max(9.0, per_attempt + 2.0),
            )
            xml = valid_xml(direct)
            if xml:
                return xml
            last_error = RuntimeError("dump direto não retornou um XML válido")
        except (OSError, subprocess.SubprocessError, RuntimeError) as error:
            last_error = error
        raise RuntimeError(f"Não foi possível capturar o XML após {attempts} tentativas: {last_error}")

    def try_ui_xml(self, timeout: float = 4) -> str:
        """Obtém o XML sem confundir uma falha transitória com XML ausente.

        O ``uiautomator`` do Android às vezes fica preso por alguns segundos e
        volta a responder sozinho. Antes, essa condição retornava uma string
        vazia e os grupos Nav-R/Nav-S a tratavam como "elemento não
        encontrado", consumindo as tentativas e seguindo o fluxo errado.
        Aqui a captura é recuperada até haver um XML válido — ou até a
        execução ser parada — para que somente uma captura bem-sucedida possa
        participar de uma decisão de fluxo.
        """
        stop_event = getattr(self, "xml_stop_event", None)
        recovery_callback = getattr(self, "xml_recovery_callback", None)
        recovery_round = 0
        while stop_event is None or not stop_event.is_set():
            try:
                # Na execução normal, cada lote de captura usa a limpeza root
                # desde a primeira falha. O modo padrão continua mais leve
                # para consultas isoladas e testes locais.
                xml = self.ui_xml(timeout=timeout, force_root_recovery=True)
                if xml and "<" in xml:
                    if recovery_round and callable(recovery_callback):
                        recovery_callback("restored", recovery_round)
                    return xml
            except (OSError, subprocess.SubprocessError, RuntimeError):
                pass
            recovery_round += 1
            if callable(recovery_callback):
                # A recuperação não libera a etapa: continua forçando novos
                # dumps até obter XML válido ou a pessoa parar a execução.
                recovery_callback("waiting" if recovery_round == 1 else "retrying", recovery_round)
            # A limpeza já é feita em ``ui_xml``. Aguarda pouco e tenta de
            # novo, sem sobrecarregar o aparelho enquanto ele se recupera.
            pause_s = min(2.0, 0.35 * recovery_round)
            if stop_event is not None:
                if stop_event.wait(pause_s):
                    break
            else:
                time.sleep(pause_s)
        return ""

    def keep_awake(self, enabled: bool) -> None:
        """Mantem a tela ligada somente enquanto uma operacao estiver ativa."""
        try:
            self.command("shell", "svc", "power", "stayon", "usb" if enabled else "false")
        except (OSError, subprocess.SubprocessError, RuntimeError):
            # Alguns fabricantes restringem esse comando; a macro segue normal.
            pass

    def show_touches(self, enabled: bool) -> None:
        """Define persistentemente o indicador visual de toques do aparelho."""
        try:
            self.command("shell", "settings", "put", "system", "show_touches", "1" if enabled else "0", timeout=5)
        except (OSError, subprocess.SubprocessError, RuntimeError):
            pass

    def show_pointer_location(self, enabled: bool) -> None:
        """Mostra o traço e as coordenadas dos eventos injetados pelo ADB."""
        try:
            self.command("shell", "settings", "put", "system", "pointer_location", "1" if enabled else "0", timeout=5)
        except (OSError, subprocess.SubprocessError, RuntimeError):
            pass

    def screenshot(self) -> bytes:
        command = [self.path]
        if self.serial:
            command += ["-s", self.serial]
        command += ["exec-out", "screencap", "-p"]
        run = subprocess.run(command, capture_output=True, timeout=12, creationflags=NO_CONSOLE)
        if run.returncode or not run.stdout:
            raise RuntimeError(run.stderr.decode("utf-8", "replace").strip() or "Não consegui capturar a tela.")
        return run.stdout


class TouchRecorder:
    """Converte um único toque/arrasto de getevent em Actions.

    O formato de `getevent` e a escala do touchscreen mudam por aparelho.
    A escala é estimada a partir da maior coordenada vista durante a gravação.
    Para obter máxima precisão, ajuste o tamanho bruto nos campos da interface.
    """
    EVENT = re.compile(
        r"\[\s*(?P<t>[\d.]+)\]\s+(?P<device>/dev/input/event\d+):\s+(?:EV_(?:ABS|KEY|SYN)\s+)?"
        r"(?P<name>ABS_(?:MT_)?(?:POSITION_[XY]|TRACKING_ID)|BTN_TOUCH|KEY_(?:BACK|HOME|APPSELECT|MENU|POWER)|SYN_REPORT)\s+"
        r"(?P<value>[0-9a-fA-F]+|DOWN|UP)"
    )

    def __init__(self, adb: Adb, screen: tuple[int, int], raw_size: tuple[int, int], on_action,
                 initial_delay_ms: int = 400, recording_started_at: float | None = None) -> None:
        self.adb, self.screen, self.raw_size, self.on_action = adb, screen, raw_size, on_action
        self.initial_delay_ms = initial_delay_ms
        self.recording_started_at = recording_started_at or time.monotonic()
        self.first_action_started_at: float | None = None
        self.stop_event = threading.Event()
        self.process: subprocess.Popen | None = None
        self.x = self.y = None
        self.start: tuple[int, int, float] | None = None
        self.began_at: float | None = None
        self.previous_end: float | None = None
        self.touch_device: str | None = None
        self.input_device: str | None = None

    def _delay_before_action(self, began: float) -> int:
        if self.previous_end is None:
            started = self.first_action_started_at or time.monotonic()
            measured = round((started - self.recording_started_at) * 1000)
        else:
            measured = round((began - self.previous_end) * 1000)
        return max(self.initial_delay_ms, measured)

    def stop(self) -> None:
        self.stop_event.set()
        if self.process and self.process.poll() is None:
            # `adb shell getevent` cria um processo filho no Windows. Apenas
            # terminar adb pode deixar o pipe aberto e a thread bloqueada;
            # encerre exclusivamente a árvore iniciada por esta gravação.
            try:
                # Nunca espere pelo taskkill na interface: em alguns drivers o
                # Windows demora para encerrar a árvore do adb.
                subprocess.Popen(["taskkill", "/PID", str(self.process.pid), "/T", "/F"],
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                 creationflags=NO_CONSOLE)
            except (OSError, subprocess.SubprocessError):
                try:
                    self.process.terminate()
                except OSError:
                    pass

    def _xy(self) -> tuple[int, int] | None:
        if self.x is None or self.y is None:
            return None
        rw, rh = self.raw_size
        sw, sh = self.screen
        return (max(0, min(sw - 1, round(self.x * (sw - 1) / max(1, rw - 1)))),
                max(0, min(sh - 1, round(self.y * (sh - 1) / max(1, rh - 1)))))

    def _finish_touch(self, timestamp: float) -> None:
        if not self.start:
            self.began_at = None
            self.touch_device = None
            return
        end = self._xy() or self.start[:2]
        sx, sy, began = self.start
        duration = max(40, round((timestamp - began) * 1000))
        delay = self._delay_before_action(began)
        distance = abs(end[0] - sx) + abs(end[1] - sy)
        self.on_action(Action("tap" if distance < 35 else "swipe", sx, sy,
                              None if distance < 35 else end[0], None if distance < 35 else end[1], duration, delay))
        self.previous_end = timestamp
        self.start = None
        self.began_at = None
        self.touch_device = None

    def run(self) -> None:
        command = [self.adb.path]
        if self.adb.serial:
            command += ["-s", self.adb.serial]
        command += ["shell", "getevent", "-lt"]
        self.process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                        text=True, encoding="utf-8", errors="replace", bufsize=1,
                                        creationflags=NO_CONSOLE)
        assert self.process.stdout
        for line in self.process.stdout:
            if self.stop_event.is_set():
                break
            match = self.EVENT.search(line)
            if not match:
                continue
            device, name, raw_value = match["device"], match["name"], match["value"]
            timestamp = float(match["t"])
            # Botões do sistema (especialmente Voltar) não geram coordenadas.
            if name.startswith("KEY_"):
                if raw_value == "DOWN":
                    keycode = "KEYCODE_" + ("APP_SWITCH" if name == "KEY_APPSELECT" else name[4:])
                    if self.previous_end is None:
                        self.first_action_started_at = time.monotonic()
                    delay = self._delay_before_action(timestamp)
                    self.on_action(Action("key", duration_ms=0, delay_ms=delay, keycode=keycode))
                    self.previous_end = timestamp
                continue
            if self.input_device is not None and device != self.input_device:
                continue
            if self.touch_device is not None and device != self.touch_device:
                continue
            if name == "BTN_TOUCH":
                continue
            if name == "SYN_REPORT":
                if self.began_at is not None and self.start is None:
                    point = self._xy()
                    if point:
                        self.start = (point[0], point[1], self.began_at)
                continue
            value = int(raw_value, 16)
            if name.endswith("POSITION_X"):
                self.x = value
            elif name.endswith("POSITION_Y"):
                self.y = value
            # Em muitos aparelhos TRACKING_ID é emitido antes das primeiras
            # coordenadas. Capturamos o início somente depois de receber X e Y.
            if name.endswith("TRACKING_ID"):
                if value != 0xFFFFFFFF:
                    if self.input_device is None:
                        self.input_device = device
                    # Não reutilize X/Y do toque anterior. Alguns aparelhos
                    # enviam TRACKING_ID antes de atualizar ambas as posições;
                    # isso fazia o início de um toque herdar uma coordenada
                    # antiga e virar um arrasto falso.
                    self.touch_device = device
                    self.start = None
                    self.began_at = timestamp
                    if self.previous_end is None:
                        self.first_action_started_at = time.monotonic()
                elif not self.start:
                    self.began_at = None
                    self.touch_device = None
                elif self.start:
                    end = self._xy() or self.start[:2]
                    sx, sy, began = self.start
                    duration = max(40, round((timestamp - began) * 1000))
                    delay = self._delay_before_action(began)
                    # Pequenos deslocamentos durante um toque são comuns e não
                    # devem transformar uma pressão em arrasto na reprodução.
                    distance = abs(end[0] - sx) + abs(end[1] - sy)
                    action = Action("tap" if distance < 35 else "swipe", sx, sy,
                                    None if distance < 35 else end[0], None if distance < 35 else end[1],
                                    duration, delay)
                    self.on_action(action)
                    self.previous_end = timestamp
                    self.start = None
                    self.began_at = None
                    self.touch_device = None


class MacroApp(tk.Tk):
    def __init__(self) -> None:
        self._set_windows_app_identity()
        super().__init__()
        self.title(APP_NAME)
        if APP_ICON.exists():
            try:
                self.iconbitmap(default=str(APP_ICON))
            except tk.TclError:
                pass
        # A moldura nativa não respeita o modo escuro nesta instalação do Windows.
        # Usamos uma barra própria para garantir o acabamento preto.
        self.geometry("1080x700")
        self.minsize(920, 620)
        self._apply_theme()
        # A janela começa maximizada depois que a barra preta for criada.
        # Alguns Windows só criam a moldura nativa depois do primeiro desenho;
        # repetimos uma vez para garantir que ela não volte ao claro.
        self.adb = Adb()
        self.recorder: TouchRecorder | None = None
        self.recorder_thread: threading.Thread | None = None
        self.record_starting = False
        self.record_prepare_cancel = threading.Event()
        self.recording_session = 0
        self.accepting_session: int | None = None
        self.recording_undo_active = False
        self.active_group: int | None = None
        self.record_insert: tuple[int, int] | None = None
        self.record_subgroup_actions: list[Action] | None = None
        self.record_subgroup_insert_index: int | None = None
        self.record_subgroup_tree_prefix: str = ""
        self.record_requested_subgroup_item: str = ""
        self.record_inline_nav_actions: list[dict] | None = None
        self.record_requested_inline_nav_item: str = ""
        self.record_requested_insert: tuple[int, int] | None = None
        self.record_previous_selection: tuple[str, ...] = ()
        self.record_previous_focus = ""
        self.last_recorded_item: str | None = None
        self.undo_stack: list[tuple[str, str, list[dict], tuple[str, ...], str]] = []
        self.redo_stack: list[tuple[str, str, list[dict], tuple[str, ...], str]] = []
        self.macro_clipboard: list[tuple[str, object]] = []
        self.running_tree_item: str | None = None
        self.execution_open_items: set[str] = set()
        # O Esc só interrompe a execução. Guardamos a árvore como ela estava
        # naquele instante para que o encerramento assíncrono não recolha
        # grupos/subgrupos que a pessoa deixou abertos.
        self._open_items_before_stop_by_panel: dict[str, set[str]] = {}
        self.device_execution_states: dict[str, dict[str, object]] = {}
        self._run_thread_context = threading.local()
        self._fallback_run_stop_event = threading.Event()
        self.run_stop_event = PanelStopProxy(self._run_thread_context, self._fallback_run_stop_event)
        self.panel_runs: dict[str, PanelRun] = {}
        self.execution_logs_by_panel: dict[str, list[str]] = {}
        # Entradas do log que ainda precisam aparecer no widget. Manter uma
        # pequena fila evita redesenhar/rolar o Text a cada mensagem da thread.
        self._pending_log_widget_entries: list[str] = []
        # O item em execução é recebido da thread de automação. Mantê-lo no
        # estado da interface (e não numa variável local do leitor da fila)
        # impede que uma atualização visual interrompida deixe o destaque
        # preso no cabeçalho de um grupo.
        # Uma execu\u00e7\u00e3o paralela publica uma etapa por telefone. Uma \u00fanica
        # tupla aqui fazia o \u00faltimo evento sobrescrever os demais antes do
        # Tk desenhar a tela; por isso apenas um celular ficava marcado.
        self._pending_running_items: dict[str, str | None] = {}
        self._execution_ui_commit_scheduled = False
        self._suppress_status_log = False
        self.run_active = False
        # A parada é assíncrona porque uma chamada ADB já iniciada pode levar
        # alguns segundos para devolver o controle. Mantemos este estado
        # separado para não anunciar que já é seguro iniciar de novo antes de
        # todas as threads da execução anterior terminarem.
        self.execution_stopping = False
        # A parada é por painel. Um painel em encerramento não pode congelar
        # o destaque, o log ou os controles dos outros que seguem executando.
        self.stopping_panels: set[str] = set()
        # Estado de borda para o Esc global do Windows. Assim manter a tecla
        # pressionada não dispara várias paradas seguidas.
        self._global_escape_was_down = False
        self.pc_automation_escape_target: tuple[str, str] | None = None
        self.execution_refresh_pending = False
        # Cada pedido de execução recebe um número. Assim uma atualização de
        # aparelhos que terminou atrasada nunca inicia uma execução já cancelada.
        self.execution_request_token = 0
        self.record_refresh_pending = False
        self.record_request_token = 0
        self.overlay_refresh_pending = False
        self.preview_session = 0
        self.preview_photo = None
        self.preview_base_image: Image.Image | None = None
        self.preview_context: dict | None = None
        self.preview_screens: dict[str, tuple[float, Image.Image]] = {}
        self.scrcpy_process: subprocess.Popen | None = None
        self.scrcpy_window_handle = 0
        self.scrcpy_window_title = ""
        self.scrcpy_window_bounds: tuple[int, int, int, int] | None = None
        # Retângulo *cliente* medido no Windows, em pixels físicos. Não é
        # necessariamente igual ao retângulo solicitado ao scrcpy: depois de
        # reconnect/DPI o SDL pode manter uma borda invisível de alguns pixels.
        self.scrcpy_client_bounds: tuple[int, int, int, int] | None = None
        self.scrcpy_serial = ""
        self.live_view_session = 0
        self.live_view_edit_mode = False
        self._live_edit_mouse_down = False
        self._live_ctrl_record_start: tuple[int, int, float, int] | None = None
        self._live_ctrl_record_mouse_down = False
        self._live_ctrl_record_previous_end: float | None = None
        self._live_ctrl_held_since: float | None = None
        # Pedido temporário do diálogo XML para escolher um nó diretamente
        # pela tela ao vivo: serial, elementos e retorno para o diálogo.
        self.live_xml_picker: dict | None = None
        self._live_alt_passthrough = False
        self._scrcpy_original_exstyle: int | None = None
        self.live_marker_window: tk.Toplevel | None = None
        self.live_marker_canvas: tk.Canvas | None = None
        self.live_xml_marker_bounds: tuple[int, int, int, int] | None = None
        self.live_xml_marker_source_size: tuple[int, int] | None = None
        self._live_marker_in_foreground = False
        self._live_layout_pending = False
        self.grid_scrcpy_processes: dict[str, subprocess.Popen] = {}
        self.grid_scrcpy_windows: dict[str, int] = {}
        self.device_grid_hosts: dict[str, tk.Frame] = {}
        self.device_grid_screen_labels: dict[str, tk.Label] = {}
        self.device_grid_log_widgets: dict[str, tk.Text] = {}
        self.device_grid_card_widgets: dict[str, tk.Frame] = {}
        self.device_grid_title_details: dict[str, tk.Label] = {}
        self.device_grid_flow_trees: dict[str, ttk.Treeview] = {}
        self.grid_focused_panel = ""
        # Na grade de celulares cada telefone pode abrir seu próprio resumo de
        # fluxo. O estado é separado da tela principal para a grade continuar
        # naturalmente minimizada ao entrar nela.
        self.device_grid_expanded_serials: set[str] = set()
        self.device_logs_by_serial: dict[str, list[str]] = {}
        # A grade abre limpa: cada mini log só aparece quando a pessoa pedir,
        # ou automaticamente no cartão cujo fluxo compacto foi aberto.
        self.device_grid_logs_visible = False
        self.device_grid_layout_mode = "panel"
        self.grid_live_position_pollers: set[tuple[str, int, int]] = set()
        self.grid_marker_windows: dict[str, tuple[tk.Toplevel, tk.Canvas]] = {}
        self.grid_marker_selected_items: dict[str, str] = {}
        # Área XML encontrada durante a execução, independente para cada
        # telefone da grade.
        self.grid_xml_marker_bounds: dict[str, tuple[tuple[int, int, int, int], tuple[int, int]]] = {}
        self.grid_xml_picker: dict | None = None
        self.grid_xml_inspection_serial = ""
        self.grid_ctrl_record_starts: dict[str, tuple[int, int, float, int]] = {}
        self.grid_ctrl_held_since: dict[str, float] = {}
        self.grid_modified_pointer_serials: set[str] = set()
        self.grid_edit_mouse_down = False
        self.grid_alt_armed_serial = ""
        self.grid_alt_armed_at = 0.0
        self.grid_scrcpy_original_exstyles: dict[str, int] = {}
        self.grid_capture_stop = threading.Event()
        self.grid_view_session = 0
        # A visualização ao vivo é a forma padrão de acompanhar o telefone.
        # A única visualização usada é a tela ao vivo encaixada no painel.
        self.live_view_mode = True
        self.live_view_autostart_attempted = False
        self.events = PanelEventQueue(self._run_thread_context)
        self.screen = (1080, 1920)
        self.device_model = ""
        self.device_profiles: dict[str, dict[str, str]] = {}
        self.device_label_cache: dict[str, str] = {}
        self.device_calibrations: dict[str, tuple[tuple[int, int], tuple[int, int]]] = {}
        self.awake_serials: set[str] = set()
        self.screen_timeout_by_serial: dict[str, str] = {}
        self.legacy_awake_cleanup_pending = True
        self.settings = self._load_settings()
        self._ensure_number_api_settings()
        self.panels = self._load_panels()
        self.macros: dict[str, list[dict]] = {panel["id"]: [] for panel in self.panels}
        self.macro_devices: dict[str, dict] = {panel["id"]: {} for panel in self.panels}
        self.saved_names = self._load_names()
        self._load_panel_files()
        self._vars()
        self._build_scrollable_content()
        self._layout()
        self._apply_logo_palette()
        self._update_variation_controls()
        self.protocol("WM_DELETE_WINDOW", self.on_close)
        self._prepared_popup_windows: set[str] = set()
        self._live_views_hidden_by_minimize = False
        self._grid_popups_hiding_live_views: set[str] = set()
        self._grid_action_drawer_hides_live_views = False
        self.bind_all("<Map>", self._on_popup_mapped, add="+")
        self.bind("<Map>", self._restore_modal_popup, add="+")
        self.bind("<FocusIn>", self._restore_modal_popup, add="+")
        self.bind("<Unmap>", self._on_main_window_unmap, add="+")
        self.bind("<Map>", self._on_main_window_map, add="+")
        # O Windows cria a moldura em momentos diferentes conforme o PC.
        # Reaplicar logo apÃ³s abrir garante o tom escuro sem trocar a moldura
        # nativa por uma janela sem barra de tarefas.
        self.after(80, self.enable_dark_titlebar)
        self.after(300, self.enable_dark_titlebar)
        self.after(900, self.enable_dark_titlebar)
        self.after(100, self._start_maximized)
        self.after(100, self._process_events)
        self.after(60, self._poll_global_escape)
        self.after(80, self._poll_live_coordinate_editing)
        self.refresh_devices()
        self.refresh_recording_list()

    def on_close(self) -> None:
        """Restaura o comportamento de tela dos aparelhos usados pelo app."""
        for active_run in tuple(self.panel_runs.values()):
            active_run.stop_now()
        self.stop_live_view()
        self._stop_grid_live_views()
        # ``terminate`` é assíncrono e alguns scrcpy demoravam a fechar no
        # instante em que o Tk era destruído. Antes de sair, elimine e aguarde
        # toda a árvore de visualizações iniciada por esta instância.
        self._close_orphaned_scrcpy_views(wait=True)
        for serial in tuple(self.awake_serials):
            try:
                adb = Adb()
                adb.path, adb.serial = self.adb.path, serial
                adb.keep_awake(False)
                previous_timeout = self.screen_timeout_by_serial.get(serial)
                if previous_timeout:
                    adb.command("shell", "settings", "put", "system", "screen_off_timeout", previous_timeout, timeout=5)
            except Exception:
                pass
        self.destroy()

    def _start_maximized(self) -> None:
        """Abre maximizado, como uma janela normal do Windows."""
        try:
            self.state("zoomed")
        except tk.TclError:
            self.attributes("-zoomed", True)

    def _on_popup_mapped(self, event) -> None:
        """Dá foco às janelas auxiliares assim que terminarem de ser criadas."""
        window = event.widget
        if window is self or not isinstance(window, (tk.Toplevel, ctk.CTkToplevel)):
            return
        key = str(window)
        if key in self._prepared_popup_windows:
            return
        self._prepared_popup_windows.add(key)
        window.after_idle(lambda popup=window: self._prepare_popup_window(popup))

    def _restore_modal_popup(self, _event=None) -> None:
        """Ao restaurar o app, restaura também o popup modal que o bloqueia."""
        try:
            popup = self.grab_current()
            if not popup or popup is self or not popup.winfo_exists():
                return
            popup.after(30, lambda dialog=popup: self._bring_modal_popup_back(dialog))
        except tk.TclError:
            pass

    @staticmethod
    def _bring_modal_popup_back(dialog) -> None:
        try:
            if not dialog.winfo_exists():
                return
            if dialog.state() == "iconic":
                dialog.deiconify()
            dialog.lift()
        except tk.TclError:
            pass

    def _prepare_popup_window(self, window) -> None:
        """Traz um popup à frente, mostra todo o conteúdo útil e foca a edição."""
        try:
            if not window.winfo_exists():
                return
            window.update_idletasks()
            # Se o conteúdo pedir mais espaço que a geometria definida, a janela
            # cresce até caber na tela. Nunca diminuímos uma janela escolhida pelo usuário.
            screen_width, screen_height = window.winfo_screenwidth(), window.winfo_screenheight()
            width = min(max(window.winfo_width(), window.winfo_reqwidth() + 18), screen_width - 70)
            height = min(max(window.winfo_height(), window.winfo_reqheight() + 18), screen_height - 100)
            if width > window.winfo_width() or height > window.winfo_height():
                window.geometry(f"{width}x{height}")
            window.lift()
            # O scrcpy é uma janela nativa externa, posicionada sobre o canvas
            # do Tk. Em alguns Windows ela ignora o ``lift`` comum e acaba
            # cobrindo o diálogo. Elevamos o popup brevemente na ordem nativa
            # e o devolvemos logo depois ao nível normal, acima da tela viva.
            self._raise_popup_above_live_views(window)

            def focus_first_editable(widget) -> bool:
                for child in widget.winfo_children():
                    if isinstance(child, (tk.Entry, tk.Text, ttk.Entry, ctk.CTkEntry, ctk.CTkTextbox)):
                        try:
                            # ``focus_force`` faz o Windows trazer o Iggents e
                            # outras janelas do processo para frente. O foco
                            # normal basta quando o usuário abriu este diálogo.
                            child.focus_set()
                            return True
                        except tk.TclError:
                            continue
                    if focus_first_editable(child):
                        return True
                return False

            window.focus_set()
            focus_first_editable(window)
        except tk.TclError:
            pass

    def _raise_popup_above_live_views(self, window) -> None:
        """Garante que um diálogo do Iggents fique acima das janelas scrcpy."""
        try:
            if not window.winfo_exists() or window.overrideredirect():
                return
            self._suspend_grid_live_views_for_popup(window)
            user32 = ctypes.windll.user32
            handle = wintypes.HWND(window.winfo_id())
            flags = 0x0001 | 0x0002 | 0x0010 | 0x0040  # tamanho/posição/foco preservados
            # Não altere a ordem global das janelas scrcpy: usar HWND_BOTTOM
            # fazia outros programas do Windows aparecerem acima do app ao
            # abrir uma caixa de edição. O diálogo já é transitório do Iggents
            # e ``lift`` é suficiente dentro da ordem normal do aplicativo.
            window.lift()
        except (AttributeError, OSError, tk.TclError):
            pass

    def _suspend_grid_live_views_for_popup(self, popup) -> None:
        """Esconde as janelas nativas enquanto um diálogo do app estiver aberto."""
        key = str(popup)
        if key in self._grid_popups_hiding_live_views:
            return
        self._grid_popups_hiding_live_views.add(key)
        # A tela pode ficar visível provisoriamente apenas enquanto se inspeciona
        # um XML. Ao abrir qualquer outro popup (por exemplo, editar espera),
        # esse modo termina para nenhuma tela nativa cobrir o diálogo.
        inspected = str(self.grid_xml_inspection_serial or "")
        self.grid_xml_inspection_serial = ""
        if inspected:
            self.grid_xml_marker_bounds.pop(inspected, None)
            self._hide_grid_marker(inspected)
        self._hide_grid_markers()
        try:
            user32 = ctypes.windll.user32
            for hwnd in tuple(self.grid_scrcpy_windows.values()):
                if hwnd:
                    user32.ShowWindow(wintypes.HWND(hwnd), 0)  # SW_HIDE
        except (AttributeError, OSError):
            pass

        def restore(event, popup_key=key) -> None:
            if event.widget is not popup:
                return
            self._grid_popups_hiding_live_views.discard(popup_key)
            if not self._grid_popups_hiding_live_views:
                self.after(40, self._restore_grid_live_views_after_popup)

        popup.bind("<Destroy>", restore, add="+")

    def _restore_grid_live_views_after_popup(self) -> None:
        if self._grid_popups_hiding_live_views or self._live_views_hidden_by_minimize:
            return
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "celulares":
            return
        for serial, process in tuple(self.grid_scrcpy_processes.items()):
            if process.poll() is None:
                self._place_grid_live_view(serial, process.pid, self.grid_view_session)

    def _visible_user_popup_open(self) -> bool:
        """Indica se um diálogo comum está aberto sobre as telas ao vivo."""
        try:
            return any(
                isinstance(child, (tk.Toplevel, ctk.CTkToplevel))
                and child.winfo_exists()
                and child.winfo_viewable()
                and not child.overrideredirect()
                for child in self.winfo_children()
            )
        except tk.TclError:
            return False

    def _keep_screen_awake(self, adb: Adb, serial: str) -> None:
        """Mantém a tela ligada quando a etapa específica solicitar."""
        if serial not in self.screen_timeout_by_serial:
            try:
                timeout = adb.command("shell", "settings", "get", "system", "screen_off_timeout", timeout=5).strip()
                if timeout.isdecimal():
                    self.screen_timeout_by_serial[serial] = timeout
                adb.command("shell", "settings", "put", "system", "screen_off_timeout", "2147483647", timeout=5)
            except (OSError, subprocess.SubprocessError, RuntimeError):
                pass
        # `svc power stayon usb` é o mecanismo que o Android aplica enquanto o
        # aparelho está conectado por USB; o timeout máximo cobre fabricantes
        # que ignoram apenas esse serviço.
        adb.command("shell", "svc", "power", "stayon", "usb", timeout=8)
        self.awake_serials.add(serial)

    def _release_screen_awake(self, adb: Adb, serial: str) -> None:
        """Desfaz o manter ligado e restaura o tempo original do telefone."""
        try:
            adb.command("shell", "svc", "power", "stayon", "false", timeout=8)
            previous_timeout = self.screen_timeout_by_serial.pop(serial, None)
            if previous_timeout:
                adb.command("shell", "settings", "put", "system", "screen_off_timeout", previous_timeout, timeout=5)
        finally:
            self.awake_serials.discard(serial)

    @staticmethod
    def _clear_legacy_auto_awake(adb: Adb) -> None:
        """Remove somente a configuração extrema deixada por versões antigas."""
        adb.keep_awake(False)
        timeout = adb.command("shell", "settings", "get", "system", "screen_off_timeout", timeout=5).strip()
        if timeout == "2147483647":
            adb.command("shell", "settings", "put", "system", "screen_off_timeout", "30000", timeout=5)

    def enable_dark_titlebar(self) -> None:
        """Usa a barra nativa escura e o tom de destaque do iggents no Windows."""
        try:
            self.update_idletasks()
            # O modo escuro do Windows precisa ser habilitado para o processo
            # antes de pintar a moldura. Isso Ã© o mesmo caminho usado por apps
            # nativos e preserva Alt+Tab, a barra de tarefas e Ã¡reas de trabalho.
            try:
                uxtheme = ctypes.WinDLL("uxtheme")
                set_preferred_app_mode = ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_int)(135, uxtheme)
                flush_menu_themes = ctypes.WINFUNCTYPE(None)(136, uxtheme)
                set_preferred_app_mode(2)  # ForceDark
                flush_menu_themes()
            except Exception:
                pass
            value = ctypes.c_int(1)
            hwnd = ctypes.windll.user32.GetParent(self.winfo_id()) or self.winfo_id()
            dwm = ctypes.windll.dwmapi
            try:
                ctypes.windll.uxtheme.SetWindowTheme(hwnd, "DarkMode_Explorer", None)
            except Exception:
                pass
            # 20 funciona nas versões recentes; 19 mantém a compatibilidade
            # com instalações do Windows 10 que ainda usam o atributo antigo.
            # Algumas versÃµes respondem ao atributo 19 e outras ao 20. Aplicar
            # ambos Ã© inofensivo e evita a barra branca em versÃµes intermediÃ¡rias.
            dwm.DwmSetWindowAttribute(hwnd, 19, ctypes.byref(value), ctypes.sizeof(value))
            dwm.DwmSetWindowAttribute(hwnd, 20, ctypes.byref(value), ctypes.sizeof(value))
            # A cor de legenda é aplicada pelo Windows 11. No Windows 10 o
            # modo escuro acima continua sendo usado normalmente.
            caption = ctypes.c_int(0x000000)  # preto
            text = ctypes.c_int(0x00D5A7FF)   # lilás suave: #ffa7d5
            for attr, color in ((35, caption), (36, text), (38, caption)):
                dwm.DwmSetWindowAttribute(hwnd, attr, ctypes.byref(color), ctypes.sizeof(color))
            rounded = ctypes.c_int(2)
            dwm.DwmSetWindowAttribute(hwnd, 33, ctypes.byref(rounded), ctypes.sizeof(rounded))
        except Exception:
            pass

    @staticmethod
    def _set_windows_app_identity() -> None:
        """Evita que o atalho .pyw apareça como uma janela genérica do Python."""
        try:
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(WINDOWS_APP_ID)
        except Exception:
            pass

    def _build_window_chrome(self) -> None:
        """Cria uma barra de título preta, independente do tema do Windows."""
        bar = tk.Frame(self, bg="#0c0c0e", height=36, highlightthickness=1, highlightbackground="#302d35")
        bar.pack(side="top", fill="x")
        bar.pack_propagate(False)
        self.window_chrome = bar

        if APP_ICON.exists():
            try:
                icon = Image.open(APP_ICON).convert("RGBA").resize((21, 21), Image.Resampling.LANCZOS)
                self.window_chrome_icon = ImageTk.PhotoImage(icon)
                icon_label = tk.Label(bar, image=self.window_chrome_icon, bg="#0c0c0e", cursor="fleur")
                icon_label.pack(side="left", padx=(11, 7))
                icon_label.bind("<ButtonPress-1>", self._start_window_drag)
                icon_label.bind("<B1-Motion>", self._drag_window)
                icon_label.bind("<Double-Button-1>", lambda _event: self._toggle_window_maximize())
            except Exception:
                pass

        title = tk.Label(bar, text=APP_NAME, bg="#0c0c0e", fg="#f1edf5", font=("Segoe UI Semibold", 10), cursor="fleur")
        title.pack(side="left", fill="y")
        title.bind("<ButtonPress-1>", self._start_window_drag)
        title.bind("<B1-Motion>", self._drag_window)
        title.bind("<Double-Button-1>", lambda _event: self._toggle_window_maximize())

        controls = tk.Frame(bar, bg="#0c0c0e")
        controls.pack(side="right", fill="y")

        def chrome_button(text: str, command, hover: str) -> tk.Label:
            widget = tk.Label(controls, text=text, width=5, bg="#0c0c0e", fg="#d9d4df", font=("Segoe UI", 10), cursor="hand2")
            widget.pack(side="left", fill="y")
            widget.bind("<Button-1>", lambda _event: command())
            widget.bind("<Enter>", lambda _event: widget.configure(bg=hover, fg="#ffffff"))
            widget.bind("<Leave>", lambda _event: widget.configure(bg="#0c0c0e", fg="#d9d4df"))
            return widget

        chrome_button("−", self._minimize_window, "#2b2830")
        self.window_maximize_button = chrome_button("□", self._toggle_window_maximize, "#2b2830")
        chrome_button("×", self.on_close, "#bf315d")
        for widget in (bar, controls):
            widget.bind("<ButtonPress-1>", self._start_window_drag)
            widget.bind("<B1-Motion>", self._drag_window)
            widget.bind("<Double-Button-1>", lambda _event: self._toggle_window_maximize())

    @staticmethod
    def _windows_work_area() -> tuple[int, int, int, int]:
        """Área útil, sem cobrir a barra de tarefas do Windows."""
        try:
            class Rect(ctypes.Structure):
                _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                           ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
            rect = Rect()
            if ctypes.windll.user32.SystemParametersInfoW(48, 0, ctypes.byref(rect), 0):
                return rect.left, rect.top, rect.right, rect.bottom
        except Exception:
            pass
        return 0, 0, 1920, 1080

    def _maximize_window(self) -> None:
        if not self._window_maximized:
            self._normal_window_geometry = self.geometry()
        left, top, right, bottom = self._windows_work_area()
        self.geometry(f"{right - left}x{bottom - top}+{left}+{top}")
        self._window_maximized = True
        if hasattr(self, "window_maximize_button"):
            self.window_maximize_button.configure(text="❐")

    def _restore_window(self) -> None:
        self.geometry(self._normal_window_geometry)
        self._window_maximized = False
        if hasattr(self, "window_maximize_button"):
            self.window_maximize_button.configure(text="□")

    def _toggle_window_maximize(self) -> None:
        if self._window_maximized:
            self._restore_window()
        else:
            self._maximize_window()

    def _start_window_drag(self, event) -> None:
        if self._window_maximized:
            return
        self._drag_origin = (event.x_root - self.winfo_x(), event.y_root - self.winfo_y())

    def _drag_window(self, event) -> None:
        if not self._drag_origin or self._window_maximized:
            return
        dx, dy = self._drag_origin
        self.geometry(f"+{event.x_root - dx}+{event.y_root - dy}")

    def _minimize_window(self) -> None:
        self._restore_borderless_after_minimize = True
        self.overrideredirect(False)
        self.iconify()

    def _on_main_window_unmap(self, event=None) -> None:
        """Oculta as janelas nativas do scrcpy junto com o Iggents."""
        if event is not None and event.widget is not self:
            return
        self.after(20, self._hide_live_views_if_minimized)

    def _hide_live_views_if_minimized(self) -> None:
        try:
            if self.state() != "iconic":
                return
            self._live_views_hidden_by_minimize = True
            user32 = ctypes.windll.user32
            handles = [int(self.scrcpy_window_handle or 0),
                       *(int(hwnd or 0) for hwnd in self.grid_scrcpy_windows.values())]
            for hwnd in set(handles):
                if hwnd:
                    user32.ShowWindow(wintypes.HWND(hwnd), 0)  # SW_HIDE
            self._hide_live_touch_marker()
            for overlay, _canvas in self.grid_marker_windows.values():
                if overlay.winfo_exists():
                    overlay.withdraw()
        except (AttributeError, OSError, tk.TclError):
            pass

    def _on_main_window_map(self, event=None) -> None:
        if event is not None and event.widget is not self:
            return
        self.after(60, self._restore_live_views_after_minimize)

    def _restore_live_views_after_minimize(self) -> None:
        if not self._live_views_hidden_by_minimize or self.state() == "iconic":
            return
        self._live_views_hidden_by_minimize = False
        if getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares":
            for serial, process in tuple(self.grid_scrcpy_processes.items()):
                if process.poll() is None:
                    self._place_grid_live_view(serial, process.pid, self.grid_view_session)
        elif self.live_view_mode:
            self._resize_embedded_live_view(force=True)

    def _restore_borderless_window(self, _event=None) -> None:
        if not self._restore_borderless_after_minimize or self.state() == "iconic":
            return
        self._restore_borderless_after_minimize = False
        self.after(10, self._restore_borderless_chrome)

    def _restore_borderless_chrome(self) -> None:
        self.overrideredirect(True)
        if self._window_maximized:
            self._maximize_window()

    def _apply_theme(self) -> None:
        # Paleta propositalmente sóbria: fundo quase preto, cartões levemente
        # elevados e violeta discreto inspirado no novo ícone.
        ctk.set_appearance_mode("dark")
        self.configure(bg="#0d0d0f")
        style = ttk.Style(self)
        style.theme_use("clam")
        style.configure(".", background="#0d0d0f", foreground="#d6d2da", font=("Segoe UI", 10))
        style.configure("TFrame", background="#0d0d0f")
        style.configure("Card.TFrame", background="#1a1a1d")
        style.configure("TLabelframe", background="#1a1a1d", bordercolor="#36363c", relief="solid")
        style.configure("TLabelframe.Label", background="#1a1a1d", foreground="#d3b8fa", font=("Segoe UI Semibold", 10))
        style.configure("TLabel", background="#0d0d0f", foreground="#cbc7d0")
        style.configure("Card.TLabel", background="#1a1a1d", foreground="#cbc7d0")
        style.configure("TButton", background="#7038b6", foreground="#f3eef7", borderwidth=0, padding=(11, 7), font=("Segoe UI Semibold", 9))
        style.map("TButton", background=[("active", "#9958e8"), ("pressed", "#5f2fa0")])
        style.configure("TEntry", fieldbackground="#101013", foreground="#e4e0e8", insertcolor="#e4e0e8", bordercolor="#49494f", padding=5)
        style.configure("TCombobox", fieldbackground="#101013", background="#101013", foreground="#e4e0e8", arrowcolor="#c9c1d0", padding=4)
        style.map("TCombobox", fieldbackground=[("readonly", "#101013")], foreground=[("readonly", "#e4e0e8")])
        style.configure("Treeview", background="#161619", fieldbackground="#161619", foreground="#d4d0d8", rowheight=29,
                        borderwidth=0, relief="flat", bordercolor="#161619")
        style.configure("Treeview.Heading", background="#212126", foreground="#d5bbfa", relief="flat", font=("Segoe UI Semibold", 9), padding=8)
        style.map("Treeview", background=[("selected", "#7037b5")], foreground=[("selected", "#ffffff")])
        style.layout("Treeview", [("Treeview.treearea", {"sticky": "nswe"})])
        style.configure("Horizontal.TProgressbar", background="#df4b82", troughcolor="#29292e", bordercolor="#29292e", lightcolor="#df4b82", darkcolor="#df4b82")
        # Barras discretas, sem as setas e o branco intenso do tema do Windows.
        for scrollbar_style, orient in (("Vertical.TScrollbar", "vertical"), ("Horizontal.TScrollbar", "horizontal")):
            style.configure(scrollbar_style, background="#4c4358", troughcolor="#111114", bordercolor="#111114",
                            lightcolor="#4c4358", darkcolor="#4c4358", arrowcolor="#111114", width=11, arrowsize=0)
            style.map(scrollbar_style, background=[("active", "#715e86"), ("pressed", "#8a70a8")])
            if orient == "vertical":
                style.layout(scrollbar_style, [("Vertical.Scrollbar.trough", {"sticky": "ns", "children": [
                    ("Vertical.Scrollbar.thumb", {"expand": "1", "sticky": "nswe"})
                ]})])
            else:
                style.layout(scrollbar_style, [("Horizontal.Scrollbar.trough", {"sticky": "ew", "children": [
                    ("Horizontal.Scrollbar.thumb", {"expand": "1", "sticky": "nswe"})
                ]})])

    def _apply_logo_palette(self) -> None:
        """Troca as antigas superfícies azuladas por preto, grafite e violeta.

        A interface já possui muitos controles criados em momentos diferentes.
        Esta passada única conserva o funcionamento de cada um e unifica suas
        cores com os tons violeta/rosa presentes no ícone.
        """
        palette = {
            "#171b26": "#0d0d0f", "#202737": "#17171a", "#222938": "#101013",
            "#293246": "#202024", "#2a3345": "#2c2c31", "#303a4d": "#36363c",
            "#334155": "#28282d", "#374151": "#36363c", "#39455b": "#29292e",
            "#465166": "#49494f", "#4a5870": "#414147", "#5a6884": "#56565e",
            "#2f6fed": "#753dc4", "#4b82ee": "#9256e8", "#2458c8": "#5e2fa5",
            "#2d5eb8": "#7039ba", "#8fb7ff": "#c8a4ff", "#a9c7ff": "#d1b6ff",
            "#0d1119": "#0d0d0f", "#151d2b": "#1a1a1d", "#111925": "#161619",
            "#101724": "#101013", "#33435d": "#3b3b41", "#3b4b66": "#49494f",
            "#2b3850": "#29292e", "#3a4c69": "#414147", "#28364c": "#333339",
            "#2d3b52": "#393940", "#1a2536": "#212126", "#365fbe": "#7039ba",
            "#547cf0": "#7b40c9", "#6b90ff": "#9958e8", "#3f65d0": "#5f2fa0",
            "#e7edf7": "#d1ccd6", "#edf3fb": "#d5d0d9", "#eef4ff": "#d8d3dc",
            "#d5e4f4": "#cbc6d0", "#d8e4f6": "#cec9d3", "#dce5f2": "#d0cbd5",
            "#dbe5f2": "#cec9d3", "#c8d5e5": "#c4bfc9", "#b6c4d5": "#b8b3be",
            "#aebbd0": "#aaa5b1", "#aebaca": "#aaa5b1", "#9eafc5": "#9c98a3",
            "#9eafc4": "#9c98a3", "#98a7bb": "#96919d", "#8c9aaf": "#8b8692",
            "#f8fafc": "#e4e0e8", "#ffffff": "#f1edf4", "#fff7f4": "#eee9f0",
        }
        options = ("bg", "background", "fg", "foreground", "highlightbackground",
                   "selectbackground", "insertbackground", "fg_color", "border_color",
                   "hover_color", "button_color", "button_hover_color", "progress_color",
                   "text_color")

        def repaint(widget) -> None:
            for option in options:
                try:
                    value = widget.cget(option)
                    if isinstance(value, str) and value.lower() in palette:
                        widget.configure(**{option: palette[value.lower()]})
                except (tk.TclError, ValueError, AttributeError):
                    continue
            for child in widget.winfo_children():
                repaint(child)

        repaint(self.content)

    def _build_scrollable_content(self) -> None:
        """Mantém toda a interface acessível quando há muitos telefones ou etapas."""
        self.main_canvas = tk.Canvas(self, bg="#0d0d0f", highlightthickness=0, borderwidth=0)
        scrollbar = ttk.Scrollbar(self, orient="vertical", command=self.main_canvas.yview)
        def canvas_scrolled(first, last) -> None:
            scrollbar.set(first, last)
            # O scrcpy e a máscara são janelas nativas sobre a caixa Tk. Ao
            # rolar o Canvas, Tk não emite um Configure na caixa; portanto a
            # posição precisa ser recalculada também por esta rota.
            # A m\u00e1scara \u00e9 uma janela nativa separada. Esconda-a j\u00e1 no
            # primeiro evento de rolagem para ela jamais ficar sobre uma
            # regi\u00e3o que deixou de ser a caixa do telefone.
            self._hide_live_touch_marker()
            self._schedule_live_view_layout()

        self.main_canvas.configure(yscrollcommand=canvas_scrolled)
        scrollbar.pack(side="right", fill="y")
        self.main_canvas.pack(side="left", fill="both", expand=True)
        self.content = tk.Frame(self.main_canvas, bg="#0d0d0f")
        self._content_window = self.main_canvas.create_window((0, 0), window=self.content, anchor="nw")

        def update_region(_event=None) -> None:
            bbox = self.main_canvas.bbox("all")
            if bbox:
                # O conteúdo começa sempre no topo real (0, 0). Sem essa
                # normalização o Canvas podia manter uma região negativa e
                # revelar um vazio enorme antes do cabeçalho.
                self.main_canvas.configure(scrollregion=(0, 0, max(bbox[2], self.main_canvas.winfo_width()),
                                                         max(bbox[3], self.main_canvas.winfo_height())))

        def fit_width(event) -> None:
            self.main_canvas.itemconfigure(self._content_window, width=event.width)

        self.content.bind("<Configure>", update_region)
        self.main_canvas.bind("<Configure>", fit_width)
        self.bind_all("<MouseWheel>", self._scroll_main_content, add="+")

    def _scroll_main_content(self, event) -> None:
        """Rola a página; a lista lateral só segura o scroll enquanto couber."""
        x, y = self.winfo_pointerx(), self.winfo_pointery()
        # Em Celulares, a roda sobre a lista compacta percorre somente suas
        # tarefas; a página geral não pode deslocar essa área de trabalho.
        for compact in tuple(getattr(self, "device_grid_flow_trees", {}).values()):
            try:
                if (compact.winfo_exists()
                        and compact.winfo_rootx() <= x <= compact.winfo_rootx() + compact.winfo_width()
                        and compact.winfo_rooty() <= y <= compact.winfo_rooty() + compact.winfo_height()):
                    step = -int(event.delta / 120)
                    if step:
                        compact.yview_scroll(step, "units")
                    return "break"
            except tk.TclError:
                continue
        action_canvas = getattr(self, "action_buttons_canvas", None)
        if action_canvas and action_canvas.winfo_rootx() <= x <= action_canvas.winfo_rootx() + action_canvas.winfo_width() and action_canvas.winfo_rooty() <= y <= action_canvas.winfo_rooty() + action_canvas.winfo_height():
            step = -int(event.delta / 120)
            first, last = action_canvas.yview()
            at_top = step < 0 and first <= 0.001
            at_bottom = step > 0 and last >= 0.999
            if not (at_top or at_bottom):
                action_canvas.yview_scroll(step, "units")
                return "break"
        if self.main_canvas.winfo_rootx() <= x <= self.main_canvas.winfo_rootx() + self.main_canvas.winfo_width() and self.main_canvas.winfo_rooty() <= y <= self.main_canvas.winfo_rooty() + self.main_canvas.winfo_height():
            self.main_canvas.yview_scroll(-int(event.delta / 120), "units")
        return "break"

    def _schedule_live_view_layout(self) -> None:
        """Reposiciona/hide a máscara quando o conteúdo principal é rolado."""
        if self._live_layout_pending:
            return
        self._live_layout_pending = True

        def apply_layout() -> None:
            self._live_layout_pending = False
            if not getattr(self, "live_view_mode", False) or not hasattr(self, "preview_canvas"):
                self._hide_live_touch_marker()
                return
            try:
                if not self.preview_canvas.winfo_ismapped():
                    self._hide_live_touch_marker()
                    return
                # Se a caixa da tela saiu do viewport da interface, nenhuma
                # parte da máscara pode ficar solta sobre o restante da janela.
                if hasattr(self, "main_canvas"):
                    px, py = self.preview_canvas.winfo_rootx(), self.preview_canvas.winfo_rooty()
                    pw, ph = self.preview_canvas.winfo_width(), self.preview_canvas.winfo_height()
                    cx, cy = self.main_canvas.winfo_rootx(), self.main_canvas.winfo_rooty()
                    cw, ch = self.main_canvas.winfo_width(), self.main_canvas.winfo_height()
                    if px + pw <= cx or px >= cx + cw or py + ph <= cy or py >= cy + ch:
                        self._hide_live_touch_marker()
                        return
                self._resize_embedded_live_view(force=True)
            except tk.TclError:
                self._hide_live_touch_marker()

        self.after_idle(apply_layout)

    def _scroll_stage_tree(self, event):
        """Com o mouse na lista central, a roda nunca rola a página geral."""
        step = -int(event.delta / 120)
        if not step:
            return "break"
        self.tree.yview_scroll(step, "units")
        return "break"

    def _scroll_execution_log(self, event):
        step = -int(event.delta / 120)
        if not step:
            return "break"
        self.inline_log_text.yview_scroll(step, "units")
        return "break"

    def _scroll_embedded_panel_widget(self, event, widget) -> str:
        """Rola só o componente compacto sob o mouse, nunca a página geral."""
        step = -int(event.delta / 120)
        if step:
            widget.yview_scroll(step, "units")
        return "break"

    def _resize_stage_columns(self, event=None) -> None:
        """Mantém todas as colunas visíveis dentro da largura da lista."""
        if not hasattr(self, "tree"):
            return
        available = max(1, int(event.width if event else self.tree.winfo_width()))
        # Grupo, ação, início, fim, duração, espera. Os mínimos impedem que
        # cabeçalhos e tempos fiquem ilegíveis em janelas menores.
        weights = (0.30, 0.14, 0.18, 0.18, 0.11, 0.09)
        minimums = (155, 82, 96, 96, 72, 62)
        widths = [max(minimum, round(available * weight)) for weight, minimum in zip(weights, minimums)]
        overflow = sum(widths) - available
        if overflow > 0:
            # Reduz as colunas de texto primeiro, preservando os campos de
            # duração e espera que normalmente são valores curtos.
            for index in (0, 2, 3, 1):
                reducible = max(0, widths[index] - minimums[index])
                cut = min(reducible, overflow)
                widths[index] -= cut
                overflow -= cut
                if overflow <= 0:
                    break
        for column, width in zip(("#0", "kind", "start", "end", "duration", "delay"), widths):
            self.tree.column(column, width=width)

    def _align_device_status_indicators(self) -> None:
        """Desenha cada indicador no centro exato da linha correspondente."""
        if not hasattr(self, "device_status_canvas"):
            return
        canvas = self.device_status_canvas
        canvas.delete("all")
        rail_height = self.device_list.winfo_height()
        canvas.configure(height=rail_height)
        self.device_switch_rail.configure(height=rail_height)
        for index, state in enumerate(self.device_status_states):
            bounds = self.device_list.bbox(index)
            if not bounds:
                continue
            _x, y, _width, height = bounds
            center_y = y + height / 2
            color = "#22c55e" if state == "device" else "#7c8798"
            canvas.create_oval(9, center_y - 4, 17, center_y + 4, fill=color, outline="")
        for index, switch in enumerate(self.device_row_switches):
            bounds = self.device_list.bbox(index)
            if not bounds or index >= len(self.device_status_states) or self.device_status_states[index] != "device":
                switch.place_forget()
                continue
            _x, y, _width, height = bounds
            switch.place(x=0, y=round(y + (height - 20) / 2))
        for index, switch in enumerate(self.device_screen_switches):
            bounds = self.device_list.bbox(index)
            if not bounds or index >= len(self.device_status_states) or self.device_status_states[index] != "device":
                switch.place_forget()
                continue
            _x, y, _width, height = bounds
            switch.place(x=112, y=round(y + (height - 20) / 2))

    def _vars(self) -> None:
        self.flow_var = tk.StringVar(value=self.panels[0]["id"])
        self.version_var = tk.StringVar(value="Versão 1 (atual)")
        self.version_paths: dict[str, Path] = {}
        self.current_version_label = "Versão 1 (atual)"
        self.version_menu_updating = False
        self.nickname_var = tk.StringVar()
        self.model_var = tk.StringVar()
        self.device_active_var = tk.BooleanVar(value=True)
        self.recording_choice = tk.StringVar()
        self.raw_x_var = tk.StringVar(value="1080")
        self.raw_y_var = tk.StringVar(value="1920")
        legacy_delay_jitter = str(self.settings.get("delay_jitter", "20"))
        self.delay_jitter_down = tk.StringVar(value=str(self.settings.get("delay_jitter_down", legacy_delay_jitter)))
        self.delay_jitter_up = tk.StringVar(value=str(self.settings.get("delay_jitter_up", legacy_delay_jitter)))
        self.position_jitter = tk.StringVar(value=str(self.settings.get("position_jitter", "0")))
        self.end_position_jitter = tk.StringVar(value=str(self.settings.get("end_position_jitter", self.settings.get("position_jitter", "0"))))
        self.speed_jitter = tk.StringVar(value=str(self.settings.get("speed_jitter", "15")))
        self.variations_enabled = tk.BooleanVar(value=bool(self.settings.get("variations_enabled", True)))
        try:
            saved_minimum_delay = max(0, int(self.settings.get("minimum_delay", 400)))
        except (TypeError, ValueError):
            saved_minimum_delay = 400
        self.minimum_delay = tk.StringVar(value=str(saved_minimum_delay))
        self.start_delay_max = tk.StringVar(value=str(self.settings.get("start_delay_max", "0")))
        self.show_touches_var = tk.BooleanVar(value=bool(self.settings.get("show_touches", False)))
        self.progress_value = tk.DoubleVar(value=0)
        self.progress_text = tk.StringVar(value="Aguardando execução.")
        self.action_search_var = tk.StringVar()
        self.action_search_count = tk.StringVar()
        self.tree_search_var = tk.StringVar()
        self.tree_search_count = tk.StringVar()
        self._tree_search_matches: list[str] = []
        self._tree_search_index = -1
        self.execution_log: list[str] = []
        self.nav_rc_debug_xml: dict[str, list[tuple[str, str]]] = {}
        self.log_window: tk.Toplevel | None = None
        self.log_text: tk.Text | None = None
        self.inline_log_text: tk.Text | None = None
        self._last_logged_status = ""
        for variable in (self.delay_jitter_down, self.delay_jitter_up, self.position_jitter, self.end_position_jitter, self.speed_jitter, self.minimum_delay, self.start_delay_max, self.show_touches_var, self.variations_enabled):
            variable.trace_add("write", self._save_settings)
        self.variations_enabled.trace_add("write", self._update_variation_controls)
        self.action_search_var.trace_add("write", self._filter_action_buttons)
        self.tree_search_var.trace_add("write", self._filter_tree_steps)
        self.status = tk.StringVar(value="Conecte o telefone e autorize a depuração USB.")
        self.status.trace_add("write", self._status_to_log)

    def _update_variation_controls(self, *_args) -> None:
        """Mantém visíveis os valores, mas deixa claro quando não são usados."""
        if not hasattr(self, "variation_entries"):
            return
        state = "normal" if self.variations_enabled.get() else "disabled"
        for entry in self.variation_entries:
            entry.configure(state=state)
        if hasattr(self, "status"):
            self.status.set("Novas etapas gravadas usarão variações." if self.variations_enabled.get()
                            else "Novas etapas gravadas ficarão sem variações.")

    def _layout(self) -> None:
        root = self.content
        flows = tk.Frame(root, bg="#0d0d0f", height=42)
        flows.pack(fill="x", padx=60, pady=(12, 8))
        flows.pack_propagate(False)
        switch = tk.Frame(flows, bg="#0d0d0f")
        switch.pack(anchor="w", fill="y")
        self.flow_switch = switch
        self.flow_buttons = {}
        self._build_flow_buttons()
        views = tk.Frame(flows, bg="#0d0d0f")
        views.place(relx=1.0, rely=0.5, anchor="e")
        self.app_view_var = tk.StringVar(value="fluxo")
        self.view_flow_button = ctk.CTkButton(views, text="Fluxo", command=lambda: self.show_app_view("fluxo"),
                                              width=82, height=30, corner_radius=8,
                                              fg_color="#3c285f", hover_color="#523682")
        self.view_flow_button.pack(side="left", padx=(0, 6))
        self.view_devices_button = ctk.CTkButton(views, text="Celulares", command=lambda: self.show_app_view("celulares"),
                                                 width=92, height=30, corner_radius=8,
                                                 fg_color="#2b3850", hover_color="#3a4c69")
        self.view_devices_button.pack(side="left")

        # A faixa superior tem uma altura fechada: a lista de telefones e o
        # perfil terminam exatamente na mesma base.  Os comandos de execução
        # ocupam o espaço livre abaixo da lista, sem criar uma segunda faixa
        # vazia abaixo dos dois cartões.
        bar = ttk.Frame(root, style="Card.TFrame", padding=12, height=262)
        bar.pack(fill="x", padx=60, pady=(0, 8))
        bar.pack_propagate(False)
        bar.grid_propagate(False)
        bar.grid_columnconfigure(0, minsize=930)
        bar.grid_columnconfigure(1, minsize=520, weight=1)
        bar.grid_rowconfigure(1, minsize=205, weight=0)
        device_header = tk.Frame(bar, bg="#151d2b")
        device_header.grid(row=0, column=0, sticky="ew", pady=(0, 2))
        tk.Label(device_header, text=f"{'MODELO / GRUPO':<22} {'APELIDO':<20} {'CÓDIGO':<20} {'NOME / @':<26} {'PROXY':<22} {'EXECUÇÃO':<18}",
                 bg="#151d2b", fg="#a9b5c8", font=("Consolas", 9), anchor="w").pack(side="left", padx=(42, 0))
        ctk.CTkButton(device_header, text="⟳ Atualizar", command=self.refresh_devices, width=104, height=26, corner_radius=7,
                      fg_color="#292d35", hover_color="#393e48").pack(side="right", padx=(0, 5), pady=1)
        self.device_area = tk.Frame(bar, bg="#111925", height=205,
                                    highlightthickness=1, highlightbackground="#33435d")
        self.device_area.grid(row=1, column=0, pady=(5, 0), sticky="nsew")
        self.device_area.pack_propagate(False)
        # A lista ocupa somente o espaço necessário; os comandos de execução
        # ficam na faixa livre abaixo dela, sem alongar o painel do perfil.
        self.device_list_content = tk.Frame(self.device_area, bg="#111925")
        # A lista não deve esticar até o fim do cartão: deixa a faixa dos
        # controles logo abaixo e mantém a base alinhada ao perfil à direita.
        # Reserva uma faixa fixa para os comandos abaixo.  Usar ``place``
        # aqui evita que o Listbox absorva toda a altura do cartão e esconda
        # os botões de execução quando a lista é atualizada.
        self.device_list_content.place(x=0, y=0, relwidth=1, height=112)
        self.device_list = tk.Listbox(self.device_list_content, height=4, width=88, selectmode=tk.EXTENDED, exportselection=False)
        self.device_list.configure(background="#111925", foreground="#e7edf7", selectbackground="#365fbe",
                                   selectforeground="#ffffff", highlightthickness=0, borderwidth=0,
                                   font=("Consolas", 10), activestyle="none", relief="flat")
        self.device_status_canvas = tk.Canvas(self.device_list_content, bg="#111925", width=28,
                                              highlightthickness=0, borderwidth=0)
        self.device_status_canvas.pack(side="left", fill="y", padx=(7, 0), pady=1)
        self.device_status_states: list[str] = []
        self.device_list.pack(side="left", fill="both", expand=True, padx=(1, 0), pady=1)
        self.device_list.bind("<<ListboxSelect>>", self.populate_profile)
        self.device_switch_rail = tk.Frame(self.device_list_content, bg="#111925", width=236)
        self.device_switch_rail.pack(side="left", fill="y", padx=(4, 8), pady=1)
        self.device_switch_rail.pack_propagate(False)
        self.device_row_switches: list[ctk.CTkSwitch] = []
        self.device_screen_switches: list[ctk.CTkSwitch] = []
        profile_panel = tk.Frame(bar, bg="#11141a", height=205, padx=12, pady=8,
                                 highlightthickness=1, highlightbackground="#3a404b")
        profile_panel.grid(row=1, column=1, padx=(14, 0), pady=(5, 0), sticky="nsew")
        profile_panel.grid_propagate(False)
        profile_panel.grid_columnconfigure(0, minsize=52)
        profile_panel.grid_columnconfigure(1, weight=1)
        profile_panel.grid_columnconfigure(2, minsize=136)
        profile_panel.grid_columnconfigure(3, weight=1)
        tk.Label(profile_panel, text="Apelido:", bg="#11141a", fg="#e4e9f2", font=("Segoe UI", 11)).grid(row=0, column=0, pady=(1, 0), sticky="w")
        ctk.CTkEntry(profile_panel, textvariable=self.nickname_var, width=220, height=30, corner_radius=8,
                     fg_color="#0d1015", border_color="#484e59", text_color="#f8fafc").grid(row=0, column=1, pady=(1, 0), sticky="ew", padx=(0, 16))
        self.model_label = tk.Label(profile_panel, text="Modelo/grupo do painel:", bg="#11141a", fg="#e4e9f2", font=("Segoe UI", 10))
        self.model_label.grid(row=0, column=2, pady=(1, 0), sticky="w")
        ctk.CTkEntry(profile_panel, textvariable=self.model_var, width=180, height=30, corner_radius=8,
                     fg_color="#0d1015", border_color="#484e59", text_color="#f8fafc").grid(row=0, column=3, pady=(1, 0), sticky="ew", padx=(0, 0))
        ctk.CTkButton(profile_panel, text="▣  Salvar perfil", command=self.save_nickname, width=132, height=30, corner_radius=8,
                      fg_color="#292d35", hover_color="#393e48").grid(row=1, column=1, pady=(7, 0), sticky="w")
        ctk.CTkButton(profile_panel, text="☺  Configurar emojis", command=self.setup_adb_keyboard, width=164, height=30, corner_radius=8,
                      fg_color="#292d35", hover_color="#393e48").grid(row=1, column=2, pady=(7, 0), sticky="w")
        ctk.CTkButton(profile_panel, text="♙  Conta normal", command=self.manage_fixed_accounts, width=142, height=30, corner_radius=8,
                      fg_color="#292d35", hover_color="#393e48").grid(row=1, column=3, pady=(7, 0), sticky="w")
        ttk.Label(bar, text="Escala de toque X/Y:").grid(row=5, column=0, pady=(10, 0), sticky="w")
        ctk.CTkEntry(bar, textvariable=self.raw_x_var, width=54, height=30, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(row=5, column=1, pady=(10, 0), sticky="w", padx=6)
        ctk.CTkEntry(bar, textvariable=self.raw_y_var, width=54, height=30, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(row=5, column=1, pady=(10, 0), sticky="w", padx=(70, 0))

        # A escala é detectada automaticamente; os controles permanecem
        # internos para salvar a calibração, mas não são exibidos.
        for widget in bar.grid_slaves(row=5):
            # Painéis que começam acima podem ocupar a linha 5 por rowspan;
            # escondemos somente os controles de escala que realmente começam nela.
            if int(widget.grid_info().get("row", -1)) == 5:
                widget.grid_remove()

        # Controles dentro da área livre da lista. A lista e o perfil dividem
        # a mesma linha e, por isso, os dois cartões terminam alinhados.
        controls = tk.Frame(self.device_area, bg="#11141a", padx=8, pady=6,
                            highlightthickness=1, highlightbackground="#3a404b")
        controls.place(x=7, y=116, relwidth=1, width=-14, height=82)
        controls.grid_columnconfigure(0, weight=1)

        # Cada faixa possui sua própria grade: o seletor de versão não desloca
        # os botões principais da primeira linha.
        action_row = tk.Frame(controls, bg="#11141a")
