        def add_action_button(text, command, search_terms="", pady=3):
            # Os atalhos de inclusão recolhem a gaveta logo após a escolha.
            # Isso também cobre etapas que abrem uma janela de configuração
            # antes de serem efetivamente gravadas no fluxo.
            adds_stage = text.startswith("+") or text in {
                "Novo grupo", "XML: reiniciar loop", "Nav-R-C: usar arrasto na busca",
                "Número: comprar", "Número: obter código",
            }

            def invoke() -> None:
                command()
                if adds_stage and getattr(self, "action_drawer_open", False):
                    self.after_idle(self._minimize_action_drawer)

            button = ttk.Button(buttons, text=text, command=invoke)
            options = {"fill": "x", "pady": pady}
            button.pack(**options)
            self._action_buttons.append((button, f"{text} {search_terms}".casefold(), options, invoke))
            return button

        def update_action_scroll(_event=None):
            actions_canvas.configure(scrollregion=actions_canvas.bbox("all"))

        def resize_action_buttons(event):
            actions_canvas.itemconfigure(buttons_window, width=event.width)

        buttons.bind("<Configure>", update_action_scroll)
        actions_canvas.bind("<Configure>", resize_action_buttons)
