        add_action_button("Chance do toque", self.configure_tap_chance, "toque probabilidade chance percentual")
        add_action_button("Gerenciar títulos de links", self.manage_link_titles, "titulos links lista editar")
        add_action_button("Gerenciar textos aleatórios", self.manage_random_texts, "textos lista editar")
        add_action_button("Gerenciar legendas", lambda: self.manage_text_list(CAPTIONS_FILE, "Legendas"), "legenda lista json editar")
        add_action_button("Gerenciar hashtags", lambda: self.manage_text_list(HASHTAGS_FILE, "Hashtags"), "hashtags # lista json editar")
