        add_action_button("+ Nome de usuário", self.add_username_action, "usuario")
        add_action_button("+ Limpar campo", self.add_clear_text_action, "texto apagar")
        add_action_button("+ Data de nascimento", self.add_birthdate_action, "aniversario")
        add_action_button("+ Executar BAT", self.add_adb_command_actions, "bat script terminal comando android")
        add_action_button("+ Ligar e desbloquear tela", self.add_unlock_screen_action, "ligar acordar desbloquear tela bloqueada deslizar")
        add_action_button("+ Manter tela ligada", self.add_keep_screen_on_action, "tela ligada não apagar escurecer")
        add_action_button("+ Desligar tela", self.add_screen_off_action, "desligar tela apagar desativar manter ligado")
        add_action_button("+ Volume máximo", lambda: self.add_volume_action("max"), "volume som áudio aumentar máximo")
        add_action_button("+ Volume mínimo", lambda: self.add_volume_action("min"), "volume som áudio reduzir mínimo silenciar")
        add_action_button("+ Modo avião 15 s", self.add_airplane_mode_action, "modo aviao rede internet reconectar")
        add_action_button("+ Configurar proxy", self.add_proxy_action, "proxy proxydroid host porta usuario senha conectar")
        add_action_button("+ Desativar proxy", self.add_disable_proxy_action, "proxy desligar parar conexão")
        add_action_button("+ Esperar aleatório", self.add_random_wait_action, "esperar pausa intervalo tempo aleatorio")
        add_action_button("+ Divisão de horários", self.add_schedule_divider_action, "horario concluido aguardar intervalo proxima postagem")
