    def manage_training_users(self) -> None:
        """Mostra o usuário de treino do telefone e permite manter sua lista."""
        try:
            users = [dict(user) for user in load_random_users()]
        except RuntimeError as error:
            messagebox.showerror("Usuários de treino", str(error), parent=self)
            return
        selected_profiles = self.selected_profiles()
        serial = str(selected_profiles[0].get("serial", "")) if selected_profiles else str(self.adb.serial or "")
        current = ""
        if serial:
            try:
                current = str(RuntimeVariables(serial, RUNTIME_DIR).get("USUARIO_ALEATORIO_TREINO", "")).strip()
            except (OSError, RuntimeError, ValueError):
                pass

        dialog = tk.Toplevel(self)
        dialog.title("Usuários aleatórios de treino")
        dialog.geometry("560x500")
        dialog.minsize(500, 420)
        dialog.configure(bg="#171b26")
        dialog.transient(self); dialog.grab_set()
        current_text = (f"Usuário atual deste celular: {current}" if current
                        else "Usuário atual deste celular: ainda não foi sorteado nesta sessão.")
        current_var = tk.StringVar(value=current_text)
        ttk.Label(dialog, textvariable=current_var, wraplength=520).pack(anchor="w", padx=18, pady=(18, 8))
        ttk.Label(dialog, text="Lista usada pela etapa ‘Usuário aleatório treino’:").pack(anchor="w", padx=18)
        list_frame = ttk.Frame(dialog)
        list_frame.pack(fill="both", expand=True, padx=18, pady=(8, 12))
        user_list = tk.Listbox(list_frame, exportselection=False, background="#202737", foreground="#e7edf7",
                               selectbackground="#6d3cc2", highlightthickness=0, borderwidth=0, activestyle="none")
        scrollbar = ttk.Scrollbar(list_frame, orient="vertical", command=user_list.yview)
        user_list.configure(yscrollcommand=scrollbar.set)
        user_list.pack(side="left", fill="both", expand=True); scrollbar.pack(side="right", fill="y")
        name_var = tk.StringVar()

        def refresh(select_index: int | None = None) -> None:
            user_list.delete(0, tk.END)
            for user in users:
                user_list.insert(tk.END, str(user.get("nome", "")))
            if users:
                index = min(max(0, select_index or 0), len(users) - 1)
                user_list.selection_set(index); user_list.activate(index); name_var.set(str(users[index].get("nome", "")))
            else:
                name_var.set("")

        def selected_index() -> int | None:
            picked = user_list.curselection()
            return int(picked[0]) if picked else None

        def show_selected(_event=None) -> None:
            index = selected_index()
            if index is not None:
                name_var.set(str(users[index].get("nome", "")))

        edit_frame = ttk.Frame(dialog)
        edit_frame.pack(fill="x", padx=18, pady=(0, 10))
        ttk.Label(edit_frame, text="Usuário:").pack(side="left")
        entry = ctk.CTkEntry(edit_frame, textvariable=name_var, height=32, corner_radius=8,
                             fg_color="#222938", border_color="#465166", text_color="#f8fafc")
        entry.pack(side="left", fill="x", expand=True, padx=(8, 0))

        def save_selected() -> None:
            index = selected_index()
            value = name_var.get().strip()
            if index is None or not value:
                messagebox.showwarning("Usuários de treino", "Selecione e informe um usuário válido.", parent=dialog)
                return
            users[index]["nome"] = value
            save_random_users(users); refresh(index)
            self.status.set("Lista de usuários aleatórios de treino salva.")

        def add_user() -> None:
            value = name_var.get().strip() or "novo_usuario"
            users.append({"nome": value, "link": "", "arquivos": []})
            save_random_users(users); refresh(len(users) - 1)

        def delete_user() -> None:
            index = selected_index()
            if index is None:
                return
            if len(users) == 1:
                messagebox.showwarning("Usuários de treino", "A lista precisa manter ao menos um usuário.", parent=dialog)
                return
            value = str(users[index].get("nome", ""))
            if messagebox.askyesno("Remover usuário", f"Remover ‘{value}’ da lista?", parent=dialog):
                users.pop(index); save_random_users(users); refresh(index - 1)
                self.status.set(f"Usuário de treino ‘{value}’ removido da lista.")

        buttons = ttk.Frame(dialog); buttons.pack(fill="x", padx=18, pady=(0, 18))
        ttk.Button(buttons, text="Salvar edição", command=save_selected).pack(side="left")
        ttk.Button(buttons, text="Adicionar", command=add_user).pack(side="left", padx=8)
        ttk.Button(buttons, text="Remover", command=delete_user).pack(side="left")
        ctk.CTkButton(buttons, text="Fechar", command=dialog.destroy, width=100, height=32, corner_radius=8,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right")
        user_list.bind("<<ListboxSelect>>", show_selected)
        refresh()
        self._prepare_popup_window(dialog)

    def manage_used_identities(self) -> None:
        """Permite liberar identidades específicas que já foram reservadas."""
        dialog = tk.Toplevel(self)
        dialog.title("Usuários já usados")
        dialog.geometry("950x500")
        dialog.minsize(760, 380)
        dialog.configure(bg="#171b26")
        dialog.transient(self)
        dialog.grab_set()

        header = ttk.Frame(dialog, padding=(16, 14, 16, 8))
        header.pack(fill="x")
        ttk.Label(header, text="Usuários já usados", style="Heading.TLabel").pack(anchor="w")
        ttk.Label(
            header,
            text="Selecione uma identidade e remova apenas essa reserva para poder usá-la novamente. "
                 "A identidade atualmente vinculada a um celular não é alterada.",
            wraplength=850,
        ).pack(anchor="w", pady=(5, 0))

        filter_var = tk.StringVar()
        filter_row = ttk.Frame(dialog, padding=(16, 0, 16, 8))
        filter_row.pack(fill="x")
        ttk.Label(filter_row, text="Pesquisar:").pack(side="left")
        search = ctk.CTkEntry(filter_row, textvariable=filter_var, placeholder_text="Nome, @, e-mail ou celular...",
                              width=360, height=30, corner_radius=7, fg_color="#222938",
                              border_color="#465166", text_color="#f8fafc")
        search.pack(side="left", padx=(8, 0))

        table_frame = ttk.Frame(dialog, padding=(16, 0, 16, 10))
        table_frame.pack(fill="both", expand=True)
        columns = ("nome", "usuario", "email", "celular", "data")
        table = ttk.Treeview(table_frame, columns=columns, show="headings", selectmode="browse")
        headings = {
            "nome": ("Nome", 190), "usuario": ("@", 180), "email": ("E-mail", 245),
            "celular": ("Celular", 170), "data": ("Registrado em", 145),
        }
        for column, (title, width) in headings.items():
            table.heading(column, text=title)
            table.column(column, width=width, minwidth=90, stretch=column in ("nome", "email"))
        scroll = ttk.Scrollbar(table_frame, orient="vertical", command=table.yview)
        table.configure(yscrollcommand=scroll.set)
        table.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")

        identities: list[dict[str, str]] = []
        visible: list[dict[str, str]] = []

        def refresh() -> None:
            nonlocal identities, visible
            try:
                identities = load_used_identities()
            except RuntimeError as error:
                messagebox.showerror("Usuários já usados", str(error), parent=dialog)
                identities = []
            query = filter_var.get().strip().casefold()
            visible = [
                item for item in identities
                if not query or query in " ".join(str(item.get(key, "")) for key in ("nome", "sobrenome", "usuario", "email", "celular")).casefold()
            ]
            table.delete(*table.get_children())
            for index, item in enumerate(visible):
                full_name = f"{item.get('nome', '')} {item.get('sobrenome', '')}".strip()
                user = str(item.get("usuario", "")).strip()
                table.insert("", "end", iid=str(index), values=(full_name, f"@{user}" if user else "—",
                    item.get("email", "") or "—", item.get("celular", "") or "—", item.get("reservado_em", "") or "—"))

        def release_selected() -> None:
            selected = table.selection()
            if not selected:
                messagebox.showinfo("Usuários já usados", "Selecione uma identidade para liberar.", parent=dialog)
                return
            item = visible[int(selected[0])]
            full_name = f"{item.get('nome', '')} {item.get('sobrenome', '')}".strip()
            user = str(item.get("usuario", "")).strip()
            label = f"{full_name}{' (@' + user + ')' if user else ''}".strip()
            if not messagebox.askyesno(
                "Liberar usuário",
                f"Liberar {label} para poder criar/usar novamente?\n\n"
                "Isso remove somente o registro de já usado; não altera o celular que possa estar usando essa identidade agora.",
                parent=dialog,
            ):
                return
            try:
                released = release_used_identity(str(item.get("nome", "")), str(item.get("sobrenome", "")))
            except (RuntimeError, ValueError) as error:
                messagebox.showerror("Usuários já usados", str(error), parent=dialog)
                return
            if released:
                self.status.set(f"Identidade {label} liberada para reutilização.")
                refresh()

        buttons = ttk.Frame(dialog, padding=(16, 0, 16, 14))
        buttons.pack(fill="x")
        ctk.CTkButton(buttons, text="Liberar selecionado", command=release_selected, width=150, height=32,
                      corner_radius=8, fg_color="#7c3aed", hover_color="#8b5cf6").pack(side="left")
        ttk.Button(buttons, text="Atualizar", command=refresh).pack(side="left", padx=8)
        ctk.CTkButton(buttons, text="Fechar", command=dialog.destroy, width=100, height=32, corner_radius=8,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right")
        filter_var.trace_add("write", lambda *_args: refresh())
        table.bind("<Delete>", lambda _event: release_selected())
        refresh()
        search.focus_set()
        self._prepare_popup_window(dialog)

    def manage_random_users(self) -> None:
        """Edita os arquivos e o link vinculados a cada nome aleatório."""
        try:
            users = [dict(user) for user in load_name_profiles()]
        except RuntimeError as error:
            messagebox.showerror("Usuários aleatórios", str(error))
            return
        dialog = tk.Toplevel(self)
        dialog.title("Gerenciar nomes aleatórios")
        dialog.geometry("760x440")
        dialog.configure(bg="#171b26")
        dialog.transient(self)
        dialog.grab_set()
        tk.Label(dialog, text="Nomes", bg="#171b26", fg="#dbe5f2").grid(row=0, column=0, padx=14, pady=(14, 4), sticky="w")
        name_search_var = tk.StringVar()
        ctk.CTkEntry(dialog, textvariable=name_search_var, placeholder_text="Filtrar nomes...", width=220, height=30,
                     corner_radius=7, fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(
                         row=0, column=1, padx=(0, 14), pady=(10, 4), sticky="w"
                     )
        user_list = tk.Listbox(dialog, width=25, exportselection=False, background="#202737", foreground="#e7edf7",
                               selectbackground="#2d5eb8", highlightthickness=0, borderwidth=0)
        user_list.grid(row=1, column=0, rowspan=5, padx=14, pady=(0, 14), sticky="nsew")
        form = ttk.Frame(dialog, padding=8)
        form.grid(row=1, column=1, padx=(0, 14), pady=(0, 14), sticky="nsew")
        dialog.grid_columnconfigure(1, weight=1); dialog.grid_rowconfigure(1, weight=1)
        name_var = tk.StringVar()
        ttk.Label(form, text="Nome:").grid(row=0, column=0, sticky="w")
        ttk.Entry(form, textvariable=name_var, width=55).grid(row=0, column=1, sticky="ew", padx=(6, 0))
        ttk.Label(form, text="Links (um por linha):").grid(row=1, column=0, pady=(8, 0), sticky="nw")
        links_editor = tk.Text(form, height=4, width=47, background="#202737", foreground="#e7edf7",
                               insertbackground="#f8fafc", highlightthickness=0, borderwidth=0)
        links_editor.grid(row=1, column=1, pady=(8, 0), sticky="ew", padx=(6, 0))
        ttk.Label(form, text="Arquivos enviados para Download:").grid(row=2, column=0, columnspan=2, pady=(14, 4), sticky="w")
        file_list = tk.Listbox(form, height=10, background="#202737", foreground="#e7edf7", selectbackground="#2d5eb8",
                               highlightthickness=0, borderwidth=0)
        file_list.grid(row=3, column=0, columnspan=2, sticky="nsew")
        form.grid_columnconfigure(1, weight=1); form.grid_rowconfigure(3, weight=1)

        visible_indexes: list[int] = []

        def render_users(select_index=None):
            query = name_search_var.get().strip().casefold()
            visible_indexes[:] = [index for index, user in enumerate(users)
                                  if not query or query in str(user["nome"]).casefold()]
            user_list.delete(0, tk.END)
            for index in visible_indexes:
                user_list.insert(tk.END, str(users[index]["nome"]))
            if visible_indexes:
                selected = select_index if select_index in visible_indexes else visible_indexes[0]
                user_list.selection_set(visible_indexes.index(selected)); show_selected()
            else:
                name_var.set(""); links_editor.delete("1.0", "end"); file_list.delete(0, tk.END)

        def selected_index():
            picked = user_list.curselection()
            return visible_indexes[picked[0]] if picked else None

        def save_fields():
            index = selected_index()
            if index is None:
                return False
            name = name_var.get().strip()
            if not name:
                messagebox.showwarning("Usuários aleatórios", "Informe um nome.", parent=dialog)
                return False
            users[index]["nome"] = name
            links = [line.strip() for line in links_editor.get("1.0", "end").splitlines() if line.strip()]
            users[index]["links"] = links
            users[index]["link"] = links[0] if links else ""
            return True

        def show_selected(_event=None):
            index = selected_index()
            if index is None:
                return
            user = users[index]
            name_var.set(str(user["nome"]))
            links_editor.delete("1.0", "end")
            links_editor.insert("1.0", "\n".join(user.get("links", []) or ([user.get("link", "")] if user.get("link") else [])))
            file_list.delete(0, tk.END)
            for path in user.get("arquivos", []):
                file_list.insert(tk.END, str(path))

        def new_user():
            if users and not save_fields():
                return
            users.append({"nome": "Novo nome", "link": "", "arquivos": []})
            render_users(len(users) - 1)

        def delete_user():
            index = selected_index()
            if index is None:
                return
            if len(users) == 1:
                messagebox.showwarning("Nomes aleatórios", "A lista precisa manter ao menos um nome.", parent=dialog)
                return
            if messagebox.askyesno("Excluir nome", f"Excluir {users[index]['nome']} e seus vínculos?", parent=dialog):
                users.pop(index); render_users(max(0, index - 1))

        def add_files():
            index = selected_index()
            if index is None or not save_fields():
                return
            paths = filedialog.askopenfilenames(parent=dialog, title="Escolha os arquivos deste nome")
            existing = users[index].setdefault("arquivos", [])
            for path in paths:
                if path not in existing:
                    existing.append(path)
            show_selected()

        def remove_file():
            index = selected_index(); picked = file_list.curselection()
            if index is None or not picked:
                return
            users[index]["arquivos"].pop(picked[0]); show_selected()

        def save_all():
            if not save_fields():
                return
            try:
                save_name_profiles(users)
            except RuntimeError as error:
                messagebox.showerror("Usuários aleatórios", str(error), parent=dialog)
                return
            self.status.set(f"{len(users)} nome(s) aleatório(s) salvos.")
            dialog.destroy()

        ttk.Button(dialog, text="Novo", command=new_user).grid(row=6, column=0, padx=14, pady=(0, 14), sticky="w")
        ttk.Button(dialog, text="Excluir", command=delete_user).grid(row=6, column=0, padx=(78, 0), pady=(0, 14), sticky="w")
        ttk.Button(form, text="Adicionar arquivos", command=add_files).grid(row=4, column=0, pady=(8, 0), sticky="w")
        ttk.Button(form, text="Remover selecionado", command=remove_file).grid(row=4, column=1, pady=(8, 0), sticky="e")
        ctk.CTkButton(dialog, text="Salvar alterações", command=save_all, width=150, height=32, corner_radius=8,
                      fg_color="#2f6fed", hover_color="#4b82ee").grid(row=6, column=1, padx=14, pady=(0, 14), sticky="e")
        user_list.bind("<<ListboxSelect>>", show_selected)
        name_search_var.trace_add("write", lambda *_args: render_users())
        render_users()

    def manage_random_characters(self) -> None:
        """Configura as pastas-base escolhidas aleatoriamente por identidade."""
        characters = [dict(item) for item in load_random_characters()]
        dialog = ctk.CTkToplevel(self)
        dialog.title("Gerenciar personagens")
        dialog.geometry("820x510")
        dialog.transient(self); dialog.grab_set()
        ctk.CTkLabel(dialog, text="Personagens", font=("Segoe UI Semibold", 18)).grid(row=0, column=0, columnspan=2, padx=18, pady=(18, 2), sticky="w")
        ctk.CTkLabel(dialog, text="Ao criar uma identidade, o Iggents sorteia um personagem e mantém esse vínculo no celular.",
                     text_color="#aebbd0").grid(row=1, column=0, columnspan=2, padx=18, pady=(0, 12), sticky="w")
        character_list = tk.Listbox(dialog, exportselection=False, background="#202737", foreground="#e7edf7",
                                    selectbackground="#5b32a8", highlightthickness=0, borderwidth=0, width=28)
        character_list.grid(row=2, column=0, rowspan=2, padx=(18, 10), pady=(0, 18), sticky="nsew")
        form = ctk.CTkFrame(dialog, fg_color="#171b26", corner_radius=8)
        form.grid(row=2, column=1, padx=(0, 18), pady=(0, 18), sticky="nsew")
        dialog.grid_columnconfigure(1, weight=1); dialog.grid_rowconfigure(2, weight=1)
        form.grid_columnconfigure(1, weight=1); form.grid_rowconfigure(4, weight=1)
        name_var, folder_var = tk.StringVar(), tk.StringVar()
        ctk.CTkLabel(form, text="Nome do personagem:").grid(row=0, column=0, padx=(14, 6), pady=(14, 8), sticky="w")
        ctk.CTkEntry(form, textvariable=name_var, height=30).grid(row=0, column=1, padx=(0, 14), pady=(14, 8), sticky="ew")
        ctk.CTkLabel(form, text="Pasta-base:").grid(row=1, column=0, padx=(14, 6), pady=8, sticky="w")
        ctk.CTkEntry(form, textvariable=folder_var, height=30).grid(row=1, column=1, padx=(0, 100), pady=8, sticky="ew")
        ctk.CTkButton(form, text="Escolher pasta", width=92, height=30, command=lambda: folder_var.set(filedialog.askdirectory(parent=dialog) or folder_var.get())).grid(row=1, column=1, padx=(0, 14), pady=8, sticky="e")
        ctk.CTkLabel(form, text="Links do personagem (um por linha):").grid(row=2, column=0, padx=(14, 6), pady=(8, 2), sticky="nw")
        links_editor = ctk.CTkTextbox(form, height=84, fg_color="#202737", text_color="#e7edf7")
        links_editor.grid(row=2, column=1, padx=(0, 14), pady=(8, 2), sticky="nsew")
        ctk.CTkLabel(form, text="Subpastas encontradas:").grid(row=3, column=0, padx=(14, 6), pady=(10, 2), sticky="nw")
        folders_box = tk.Listbox(form, height=7, background="#202737", foreground="#e7edf7", highlightthickness=0, borderwidth=0)
        folders_box.grid(row=3, column=1, padx=(0, 14), pady=(10, 2), sticky="nsew")

        def selected_index() -> int | None:
            chosen = character_list.curselection()
            return chosen[0] if chosen else None

        def refresh_folders() -> None:
            folders_box.delete(0, tk.END)
            root = Path(folder_var.get().strip()).expanduser()
            if root.is_dir():
                folders_box.insert(tk.END, "Raiz do personagem")
                try:
                    for child in sorted((path for path in root.iterdir() if path.is_dir()), key=lambda path: path.name.casefold()):
                        folders_box.insert(tk.END, child.name)
                except OSError:
                    pass

        def save_current() -> bool:
            index = selected_index()
            if index is None:
                return True
            name, folder = name_var.get().strip(), folder_var.get().strip()
            if not name or not folder:
                messagebox.showwarning("Personagens", "Informe o nome e a pasta do personagem.", parent=dialog)
                return False
            characters[index] = {"nome": name, "pasta": folder,
                                 "links": [line.strip() for line in links_editor.get("1.0", "end").splitlines() if line.strip()]}
            return True

        def show_selected(_event=None) -> None:
            index = selected_index()
            if index is None:
                return
            value = characters[index]
            name_var.set(str(value.get("nome", ""))); folder_var.set(str(value.get("pasta", "")))
            links_editor.delete("1.0", "end"); links_editor.insert("1.0", "\n".join(value.get("links", [])))
            refresh_folders()

        def refresh(select: int | None = None) -> None:
            character_list.delete(0, tk.END)
            for character in characters:
                character_list.insert(tk.END, str(character.get("nome", "Personagem")))
            if characters:
                index = min(max(0, select if select is not None else 0), len(characters) - 1)
                character_list.selection_set(index); show_selected()
            else:
                name_var.set(""); folder_var.set(""); links_editor.delete("1.0", "end"); folders_box.delete(0, tk.END)

        def add_character() -> None:
            if not save_current(): return
            characters.append({"nome": "Novo personagem", "pasta": "", "links": []})
            refresh(len(characters) - 1)

        def remove_character() -> None:
            index = selected_index()
            if index is not None:
                characters.pop(index); refresh(index - 1)

        def save_all() -> None:
            if not save_current(): return
            try:
                save_random_characters(characters)
            except RuntimeError as error:
                messagebox.showerror("Personagens", str(error), parent=dialog); return
            self.status.set(f"{len(characters)} personagem(ns) salvo(s).")
            dialog.destroy()

        buttons = ctk.CTkFrame(dialog, fg_color="transparent")
        buttons.grid(row=3, column=0, columnspan=2, padx=18, pady=(0, 18), sticky="ew")
        ctk.CTkButton(buttons, text="+ Personagem", command=add_character, width=120).pack(side="left")
        ctk.CTkButton(buttons, text="Excluir", command=remove_character, width=90, fg_color="#713544", hover_color="#914657").pack(side="left", padx=8)
        ctk.CTkButton(buttons, text="Salvar personagens", command=save_all, width=150, fg_color="#6f37c7", hover_color="#874de5").pack(side="right")
        character_list.bind("<<ListboxSelect>>", show_selected)
        folder_var.trace_add("write", lambda *_args: refresh_folders())
        refresh()
        self._prepare_popup_window(dialog)

