    @staticmethod
    def _pc_cursor_position() -> tuple[int, int]:
        """Lê a posição atual do cursor sem movimentá-lo."""
        if os.name != "nt":
            raise RuntimeError("A automação no PC está disponível apenas no Windows.")
        class Point(ctypes.Structure):
            _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]
        point = Point()
        if not ctypes.windll.user32.GetCursorPos(ctypes.byref(point)):
            raise RuntimeError("Não foi possível ler a posição do mouse.")
        return int(point.x), int(point.y)

    @staticmethod
    def _pc_click(x: int, y: int) -> None:
        """Move e clica usando a API nativa do Windows."""
        if os.name != "nt":
            raise RuntimeError("A automação no PC está disponível apenas no Windows.")
        user32 = ctypes.windll.user32
        if not user32.SetCursorPos(int(x), int(y)):
            raise RuntimeError("Não foi possível mover o mouse para a posição configurada.")
        user32.mouse_event(0x0002, 0, 0, 0, 0)  # botão esquerdo pressionado
        user32.mouse_event(0x0004, 0, 0, 0, 0)  # botão esquerdo solto

    @staticmethod
    def _pc_clipboard_text() -> str:
        """Lê texto Unicode da área de transferência do Windows."""
        if os.name != "nt":
            raise RuntimeError("A automação no PC está disponível apenas no Windows.")
        user32, kernel32 = ctypes.windll.user32, ctypes.windll.kernel32
        # Sem as assinaturas abaixo, o ctypes assume inteiros de 32 bits.
        # Em Windows 64 bits isso trunca o HANDLE do clipboard e gera
        # "OverflowError: int too long to convert" ao liberá-lo.
        user32.OpenClipboard.argtypes = [ctypes.c_void_p]
        user32.OpenClipboard.restype = ctypes.c_int
        user32.GetClipboardData.argtypes = [ctypes.c_uint]
        user32.GetClipboardData.restype = ctypes.c_void_p
        user32.CloseClipboard.argtypes = []
        user32.CloseClipboard.restype = ctypes.c_int
        kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalUnlock.restype = ctypes.c_int
        if not user32.OpenClipboard(None):
            raise RuntimeError("Não foi possível acessar a área de transferência do Windows.")
        try:
            handle = user32.GetClipboardData(13)  # CF_UNICODETEXT
            if not handle:
                raise RuntimeError("Não há um link em texto copiado no PC.")
            pointer = kernel32.GlobalLock(handle)
            if not pointer:
                raise RuntimeError("Não foi possível ler o texto copiado no PC.")
            try:
                return str(ctypes.wstring_at(pointer)).strip()
            finally:
                kernel32.GlobalUnlock(handle)
        finally:
            user32.CloseClipboard()

    @staticmethod
    def _pc_type_text(value: str, interval_ms: int = 100, variation_ms: int = 35) -> None:
        """Digita texto pelo teclado virtual do Windows.

        A automação no PC usa o @ da conta, que é texto simples. `keybd_event`
        é mais compatível que um lote Unicode de SendInput com alguns programas
        que recusavam o lote inteiro.
        """
        if os.name != "nt":
            raise RuntimeError("A automação no PC está disponível apenas no Windows.")
        user32 = ctypes.windll.user32
        for char in value:
            code = int(user32.VkKeyScanW(ord(char)))
            if code == -1:
                raise RuntimeError(f"O Windows não reconhece o caractere '{char}' para digitar.")
            virtual_key = code & 0xFF
            modifiers = (code >> 8) & 0xFF
            held: list[int] = []
            for bit, modifier_key in ((1, 0x10), (2, 0x11), (4, 0x12)):
                if modifiers & bit:
                    user32.keybd_event(modifier_key, 0, 0, 0)
                    held.append(modifier_key)
            user32.keybd_event(virtual_key, 0, 0, 0)
            user32.keybd_event(virtual_key, 0, 0x0002, 0)
            for modifier_key in reversed(held):
                user32.keybd_event(modifier_key, 0, 0x0002, 0)
            # Mantém uma digitação realmente sequencial, em vez de um lote
            # instantâneo que muitos campos exibem como se fosse colagem.
            actual_interval_ms = max(10, interval_ms + random.randint(-max(0, variation_ms), max(0, variation_ms)))
            if actual_interval_ms > 0:
                time.sleep(actual_interval_ms / 1000)

    @staticmethod
    def _pc_press_key(key_name: str) -> None:
        """Pressiona uma tecla do Windows pelo nome configurado."""
        if os.name != "nt":
            raise RuntimeError("A automação no PC está disponível apenas no Windows.")
        key = key_name.strip().upper()
        named_keys = {
            "ENTER": 0x0D, "TAB": 0x09, "ESC": 0x1B, "ESCAPE": 0x1B,
            "ESPAÇO": 0x20, "ESPACO": 0x20, "SPACE": 0x20,
            "BACKSPACE": 0x08, "APAGAR": 0x08, "DELETE": 0x2E,
            "UP": 0x26, "CIMA": 0x26, "DOWN": 0x28, "BAIXO": 0x28,
            "LEFT": 0x25, "ESQUERDA": 0x25, "RIGHT": 0x27, "DIREITA": 0x27,
            "HOME": 0x24, "END": 0x23,
        }
        if key in named_keys:
            virtual_key = named_keys[key]
        elif len(key) == 2 and key.startswith("F") and key[1:].isdigit() and 1 <= int(key[1:]) <= 12:
            virtual_key = 0x70 + int(key[1:]) - 1
        elif len(key) == 1:
            virtual_key = ctypes.windll.user32.VkKeyScanW(ord(key)) & 0xFF
            if virtual_key == 0xFF:
                raise RuntimeError(f"A tecla '{key_name}' não é reconhecida.")
        else:
            raise RuntimeError(f"A tecla '{key_name}' não é reconhecida.")
        ctypes.windll.user32.keybd_event(virtual_key, 0, 0, 0)
        ctypes.windll.user32.keybd_event(virtual_key, 0, 0x0002, 0)

    def add_pc_automation_action(self, action_ref: tuple[int, int] | None = None,
                                 copy_link_to_phone: bool = False,
                                 action_override: Action | None = None,
                                 tree_item: str | None = None) -> None:
        """Configura cliques locais e a digitação do @ do telefone."""
        existing_action: Action | None = None
        if action_override is not None:
            existing_action = action_override
            if existing_action.kind not in ("pc_automation", "pc_copy_link_to_phone"):
                return
            copy_link_to_phone = existing_action.kind == "pc_copy_link_to_phone"
        elif action_ref is not None:
            try:
                existing_action = self.macros[self.flow_var.get()][action_ref[0]]["actions"][action_ref[1]]
            except (IndexError, KeyError):
                return
            if existing_action.kind not in ("pc_automation", "pc_copy_link_to_phone"):
                return
            copy_link_to_phone = existing_action.kind == "pc_copy_link_to_phone"
        dialog = ctk.CTkToplevel(self)
        dialog.title("PC: copiar link para celular" if copy_link_to_phone else "Automação no PC")
        dialog.geometry("610x610")
        dialog.minsize(540, 550)
        dialog.transient(self); dialog.grab_set()
        ctk.CTkLabel(dialog, text="PC: copiar link para celular" if copy_link_to_phone else "Automação no PC", font=("Segoe UI Semibold", 18)).pack(anchor="w", padx=20, pady=(20, 4))
        description = ("Executa os cliques no Windows, pega o link copiado e o escreve no campo em foco do celular."
                       if copy_link_to_phone else "Executa cliques no Windows e digita o @ no ponto da sequência que você marcar.")
        ctk.CTkLabel(dialog, text=description,
                     text_color="#aebbd0", wraplength=560, justify="left").pack(anchor="w", padx=20, pady=(0, 10))
        ctk.CTkLabel(dialog, text="Link: área de transferência do PC" if copy_link_to_phone else "Informação para digitar: @ atual do telefone", text_color="#d8e4f6").pack(anchor="w", padx=20)
        sequence_label = "Sequência: clique (x, y, espera), DIGITAR LINK ou TECLA: nome:" if copy_link_to_phone else "Sequência: clique (x, y, espera), DIGITAR @ ou TECLA: nome:"
        ctk.CTkLabel(dialog, text=sequence_label, anchor="w").pack(fill="x", padx=20, pady=(16, 5))
        variation_row = ctk.CTkFrame(dialog, fg_color="transparent")
        variation_row.pack(fill="x", padx=20, pady=(10, 0))
        ctk.CTkLabel(variation_row, text="Variação de espera ± ms:").pack(side="left")
        delay_variation = tk.StringVar(value=str(int(getattr(existing_action, "pc_delay_variation_ms", 0) or 0)))
        ctk.CTkEntry(variation_row, textvariable=delay_variation, width=72).pack(side="left", padx=(8, 18))
        ctk.CTkLabel(variation_row, text="Variação de posição ± px:").pack(side="left")
        position_variation = tk.StringVar(value=str(int(getattr(existing_action, "pc_position_variation_px", 0) or 0)))
        ctk.CTkEntry(variation_row, textvariable=position_variation, width=72).pack(side="left", padx=(8, 0))
        typing_row = ctk.CTkFrame(dialog, fg_color="transparent")
        typing_row.pack(fill="x", padx=20, pady=(4, 0))
        ctk.CTkLabel(typing_row, text="Velocidade do @ (ms por letra):").pack(side="left")
        typing_interval = tk.StringVar(value=str(int(getattr(existing_action, "pc_typing_interval_ms", 100) or 100)))
        ctk.CTkEntry(typing_row, textvariable=typing_interval, width=72).pack(side="left", padx=(8, 18))
        ctk.CTkLabel(typing_row, text="Variação entre letras do @ ± ms:").pack(side="left")
        typing_variation = tk.StringVar(value=str(int(getattr(existing_action, "pc_typing_variation_ms", 35))))
        ctk.CTkEntry(typing_row, textvariable=typing_variation, width=72).pack(side="left", padx=(8, 0))
        clicks = ctk.CTkTextbox(dialog, height=220, fg_color="#202737", text_color="#e7edf7", wrap="none")
        clicks.pack(fill="both", expand=True, padx=20)
        if existing_action:
            lines: list[str] = []
            for step in existing_action.pc_clicks or []:
                if step.get("kind") == "type_username":
                    lines.append(f"DIGITAR @, {int(step.get('wait_ms', 1000))}")
                elif step.get("kind") == "type_clipboard_link":
                    lines.append(f"DIGITAR LINK, {int(step.get('wait_ms', 1000))}")
                elif step.get("kind") == "key":
                    lines.append(f"TECLA: {step.get('key', 'ENTER')}, {int(step.get('wait_ms', 1000))}")
                else:
                    lines.append(f"{int(step.get('x', 0))}, {int(step.get('y', 0))}, {int(step.get('wait_ms', 1000))}")
            clicks.insert("1.0", "\n".join(lines))
        ctk.CTkLabel(dialog, text="F8 captura clique. Use os botões para inserir @ ou uma tecla (Enter, Tab, Esc, espaço, setas, F1–F12).",
                     text_color="#aebbd0").pack(anchor="w", padx=20, pady=(5, 0))
        controls = ctk.CTkFrame(dialog, fg_color="transparent")
        controls.pack(fill="x", padx=20, pady=18)
        hotkey_down = False

        def append_position() -> None:
            try:
                x, y = self._pc_cursor_position()
                if clicks.get("1.0", "end").strip():
                    clicks.insert("end", "\n")
                clicks.insert("end", f"{x}, {y}, 1000")
                clicks.see("end")
            except RuntimeError as error:
                messagebox.showwarning("Automação no PC", str(error), parent=dialog)

        def monitor_capture_hotkey() -> None:
            """F8 é lido globalmente enquanto este configurador estiver aberto."""
            nonlocal hotkey_down
            if not dialog.winfo_exists():
                return
            pressed = bool(os.name == "nt" and (ctypes.windll.user32.GetAsyncKeyState(0x77) & 0x8000))
            if pressed and not hotkey_down:
                append_position()
            hotkey_down = pressed
            dialog.after(45, monitor_capture_hotkey)

        dialog.after(45, monitor_capture_hotkey)

        def insert_username() -> None:
            wait_value = simpledialog.askstring("Espera após digitar @", "Espera em ms antes da próxima ação:", initialvalue="1000", parent=dialog)
            if wait_value is None:
                return
            try:
                wait_ms = int(wait_value.strip())
                if not 0 <= wait_ms <= 60000:
                    raise ValueError
            except ValueError:
                messagebox.showwarning("Automação no PC", "Use uma espera de 0 a 60000 ms.", parent=dialog)
                return
            if clicks.get("1.0", "end").strip():
                clicks.insert("end", "\n")
            clicks.insert("end", f"DIGITAR @, {wait_ms}")
            clicks.see("end")

        if not copy_link_to_phone:
            ctk.CTkButton(controls, text="Inserir digitar @", command=insert_username, width=150, height=32,
                          fg_color="#39455b", hover_color="#4a5870").pack(side="left")
        else:
            def insert_link() -> None:
                wait_value = simpledialog.askstring("Espera após digitar link", "Espera em ms antes da próxima ação:", initialvalue="1000", parent=dialog)
                if wait_value is None:
                    return
                try:
                    wait_ms = int(wait_value.strip())
                    if not 0 <= wait_ms <= 60000:
                        raise ValueError
                except ValueError:
                    messagebox.showwarning("PC: copiar link", "Use uma espera de 0 a 60000 ms.", parent=dialog)
                    return
                if clicks.get("1.0", "end").strip():
                    clicks.insert("end", "\n")
                clicks.insert("end", f"DIGITAR LINK, {wait_ms}")
                clicks.see("end")

            ctk.CTkButton(controls, text="Inserir digitar link", command=insert_link, width=160, height=32,
                          fg_color="#39455b", hover_color="#4a5870").pack(side="left")

        def insert_key() -> None:
            key = simpledialog.askstring("Pressionar tecla", "Tecla: Enter, Tab, Esc, Espaço, setas, F1–F12 ou uma letra:", parent=dialog)
            if key is None or not key.strip():
                return
            wait_value = simpledialog.askstring("Espera após a tecla", "Espera em ms antes da próxima ação:", initialvalue="1000", parent=dialog)
            if wait_value is None:
                return
            try:
                wait_ms = int(wait_value.strip())
                if not 0 <= wait_ms <= 60000:
                    raise ValueError
            except ValueError:
                messagebox.showwarning("Automação no PC", "Use uma espera de 0 a 60000 ms.", parent=dialog)
                return
            if clicks.get("1.0", "end").strip():
                clicks.insert("end", "\n")
            clicks.insert("end", f"TECLA: {key.strip().upper()}, {wait_ms}")
            clicks.see("end")

        ctk.CTkButton(controls, text="Inserir tecla", command=insert_key, width=125, height=32,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="left", padx=(8, 0))

        def save() -> None:
            parsed: list[dict] = []
            line_no = 0
            try:
                delay_jitter_ms = int(delay_variation.get().strip() or "0")
                position_jitter_px = int(position_variation.get().strip() or "0")
                typing_interval_ms = int(typing_interval.get().strip() or "0")
                typing_jitter_ms = int(typing_variation.get().strip() or "0")
                if (not 0 <= delay_jitter_ms <= 60000 or not 0 <= position_jitter_px <= 1000
                        or not 0 <= typing_interval_ms <= 5000 or not 0 <= typing_jitter_ms <= 1000):
                    raise ValueError
                for line_no, line in enumerate(clicks.get("1.0", "end").splitlines(), 1):
                    if not line.strip():
                        continue
                    if line.strip().upper().startswith("DIGITAR LINK"):
                        link_parts = [part.strip() for part in line.split(",")]
                        wait_ms = int(link_parts[1]) if len(link_parts) > 1 else 1000
                        if len(link_parts) > 2 or not 0 <= wait_ms <= 60000:
                            raise ValueError
                        parsed.append({"kind": "type_clipboard_link", "wait_ms": wait_ms})
                        continue
                    if line.strip().upper().startswith("DIGITAR @"):
                        username_parts = [part.strip() for part in line.split(",")]
                        wait_ms = int(username_parts[1]) if len(username_parts) > 1 else 1000
                        if len(username_parts) > 2 or not 0 <= wait_ms <= 60000:
                            raise ValueError
                        parsed.append({"kind": "type_username", "wait_ms": wait_ms})
                        continue
                    if line.strip().upper().startswith("TECLA:"):
                        key_parts = [part.strip() for part in line.split(":", 1)[1].split(",")]
                        key_name = key_parts[0]
                        wait_ms = int(key_parts[1]) if len(key_parts) > 1 else 1000
                        if not key_name or not 0 <= wait_ms <= 60000:
                            raise ValueError
                        parsed.append({"kind": "key", "key": key_name, "wait_ms": wait_ms})
                        continue
                    x_text, y_text, wait_text = (part.strip() for part in line.split(","))
                    x, y, wait_ms = int(x_text), int(y_text), int(wait_text)
                    if x < 0 or y < 0 or not 0 <= wait_ms <= 60000:
                        raise ValueError
                    parsed.append({"x": x, "y": y, "wait_ms": wait_ms})
            except ValueError:
                messagebox.showwarning("Automação no PC", f"Confira a linha {line_no}. Use clique, DIGITAR @ ou TECLA: nome.", parent=dialog)
                return
            if not parsed:
                messagebox.showwarning("Automação no PC", "Adicione ao menos um clique.", parent=dialog)
                return
            if existing_action is not None:
                self.push_undo()
                existing_action.pc_clicks = parsed
                existing_action.pc_value_source = "usuario"
                existing_action.pc_delay_variation_ms = delay_jitter_ms
                existing_action.pc_position_variation_px = position_jitter_px
                existing_action.pc_typing_interval_ms = typing_interval_ms
                existing_action.pc_typing_variation_ms = typing_jitter_ms
                existing_action.label = f"PC link: {len(parsed)} ação(ões)" if copy_link_to_phone else f"PC: {len(parsed)} ação(ões)"
                self.refresh_tree()
                item = tree_item or (f"a:{action_ref[0]}:{action_ref[1]}" if action_ref is not None else "")
                if self.tree.exists(item):
                    self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
                self.save_macro(quiet=True)
                self.status.set("Automação no PC atualizada.")
            else:
                self._append_special_action(
                    Action("pc_copy_link_to_phone" if copy_link_to_phone else "pc_automation", delay_ms=0, pc_clicks=parsed, pc_value_source="usuario",
                           pc_delay_variation_ms=delay_jitter_ms, pc_position_variation_px=position_jitter_px,
                           pc_typing_interval_ms=typing_interval_ms,
                           pc_typing_variation_ms=typing_jitter_ms,
                           label=f"PC link: {len(parsed)} ação(ões)" if copy_link_to_phone else f"PC: {len(parsed)} ação(ões)"),
                    "Etapa de copiar link para o celular adicionada." if copy_link_to_phone else "Automação no PC adicionada. O mouse só será usado ao executar esta etapa.",
                )
            dialog.destroy()

        ctk.CTkButton(controls, text="Cancelar", command=dialog.destroy, width=96, height=32,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=(8, 0))
        ctk.CTkButton(controls, text="Adicionar", command=save, width=104, height=32,
                      fg_color="#2f6fed", hover_color="#4b82ee").pack(side="right")

    def add_enter_action(self) -> None:
        self._append_special_action(
            Action("enter", delay_ms=250, label="Enter / quebrar linha"),
            "Etapa de Enter adicionada."
        )

    def configure_tap_chance(self) -> None:
        selected = [item for item in self.tree.selection() if item.startswith(("a:", "s:"))]
        if not selected:
            messagebox.showwarning("Chance do toque", "Selecione uma ou mais etapas de toque.", parent=self)
            return
        groups = self.macros[self.flow_var.get()]
        taps = [groups[int(item.split(":")[1])]["actions"][int(item.split(":")[2])] for item in selected]
        if any(action.kind != "tap" for action in taps):
            messagebox.showwarning("Chance do toque", "A probabilidade pode ser configurada somente para etapas de toque.", parent=self)
            return
        current_chance = float(taps[0].tap_chance_pct)
        initial = str(int(current_chance) if current_chance.is_integer() else current_chance)
        value = simpledialog.askstring("Chance do toque", "Probabilidade de este toque acontecer (0 a 100%):", initialvalue=initial, parent=self)
        if value is None: return
        try:
            chance = float(value.replace(",", "."))
            if not 0 <= chance <= 100: raise ValueError
        except ValueError:
            messagebox.showwarning("Chance do toque", "Use um número de 0 a 100.", parent=self); return
        self.push_undo()
        for action in taps: action.tap_chance_pct = chance
        self.refresh_tree(); self.save_macro(quiet=True)
        self.status.set(f"Chance de {len(taps)} toque(s) ajustada para {chance:g}%.")

    @staticmethod
    def _adb_command_tokens(command: str) -> list[str]:
        """Converte uma linha ADB em argumentos, sem abrir um shell do Windows."""
        tokens = shlex.split(command.strip())
        if tokens and tokens[0].lower().removesuffix(".exe") == "adb":
            tokens.pop(0)
        if tokens[:1] == ["-s"]:
            raise ValueError("Não use -s: a etapa já roda no telefone correspondente.")
        if not tokens or tokens[0] not in {"shell", "reboot"}:
            raise ValueError("Use comandos iniciados por 'adb shell' ou 'adb reboot'.")
        normalized = " ".join(tokens).lower()
        blocked = (" master_clear", "factory_reset", "recovery", "wipe", " setprop", " android_id", " device_id",
                   "ro.serial", "ifconfig wlan", "ip link set", "rm -rf /data", " su ")
        if any(fragment in f" {normalized}" for fragment in blocked):
            raise ValueError("Esse comando altera identificadores ou faz reset do aparelho e não pode ser adicionado.")
        return tokens

    def add_adb_command_actions(self) -> None:
        path = filedialog.askopenfilename(parent=self, title="Escolha o arquivo BAT", filetypes=[("Arquivo BAT", "*.bat"), ("Todos os arquivos", "*.*")])
        if not path:
            return
        self.push_undo()
        action = Action("run_bat", delay_ms=400, bat_file=path, label=f"BAT: {Path(path).name}")
        self._set_action_variation_defaults(action)
        group_index, action_index = self._insert_new_action(action)
        item = f"a:{group_index}:{action_index}"
        self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set(f"BAT adicionado: {Path(path).name}. O serial será passado como primeiro argumento.")

    def add_airplane_mode_action(self) -> None:
        self._append_special_action(
            Action("airplane_mode", delay_ms=400, timeout_s=15, label="Modo avião por 15 segundos"),
            "Etapa de modo avião por 15 segundos adicionada."
        )

    def add_disable_proxy_action(self) -> None:
        self._append_special_action(
            Action("disable_proxy", delay_ms=400, label="Desativar proxy"),
            "Etapa para encerrar o proxy root deste telefone adicionada."
        )

    def _test_proxy_list(self, values: list[str], parent) -> None:
        """Testa cada proxy pelo PC e informa o IP público devolvido."""
        if not values:
            messagebox.showwarning("Testar proxies", "Informe ao menos um proxy para testar.", parent=parent)
            return
        dialog = tk.Toplevel(self)
        dialog.title("Teste de proxies")
        dialog.geometry("650x390")
        dialog.configure(bg="#171b26")
        dialog.transient(parent)
        ttk.Label(dialog, text="Testando a conexão e o IP público retornado por cada proxy…").pack(anchor="w", padx=16, pady=(16, 8))
        result = tk.Text(dialog, bg="#202737", fg="#edf3fb", insertbackground="#ffffff", relief="flat",
                         wrap="word", padx=9, pady=8, font=("Consolas", 10), state="disabled")
        result.pack(fill="both", expand=True, padx=16, pady=(0, 12))
        ctk.CTkButton(dialog, text="Fechar", command=dialog.destroy, width=90, height=30,
                      fg_color="#39455b", hover_color="#4a5870").pack(anchor="e", padx=16, pady=(0, 16))

        def append(line: str) -> None:
            def update() -> None:
                if not dialog.winfo_exists():
                    return
                result.configure(state="normal")
                result.insert("end", line + "\n")
                result.see("end")
                result.configure(state="disabled")
            self.after(0, update)

        def run_tests() -> None:
            for index, raw in enumerate(values, 1):
                parsed = None
                try:
                    parsed = urlsplit("http://" + raw)
                    if not parsed.hostname or not parsed.port or parsed.username is None or parsed.password is None:
                        raise ValueError("formato inválido")
                    username = quote(unquote(parsed.username), safe="")
                    password = quote(unquote(parsed.password), safe="")
                    proxy_url = f"http://{username}:{password}@{parsed.hostname}:{parsed.port}"
                    opener = build_opener(ProxyHandler({"http": proxy_url, "https": proxy_url}))
                    request = Request("https://api.ipify.org?format=json", headers={"User-Agent": "iggen-proxy-test/1.0"})
                    with opener.open(request, timeout=20) as response:
                        payload = json.loads(response.read().decode("utf-8"))
                    shown_ip = str(payload.get("ip", "sem IP informado")) if isinstance(payload, dict) else str(payload)
                    append(f"{index}. {parsed.hostname}:{parsed.port}  →  OK — IP {shown_ip}")
                except Exception as error:
                    host = parsed.hostname if parsed and parsed.hostname else "proxy inválido"
                    port = parsed.port if parsed and parsed.port else "--"
                    append(f"{index}. {host}:{port}  →  FALHOU — {error}")
            append("Teste concluído.")

        self._thread(run_tests)

    @staticmethod
    def _test_proxy_connection(raw: str, timeout_s: int = 15) -> tuple[bool, str]:
        """Testa um proxy HTTP autenticado e devolve o IP recebido.

        A mesma verificação é usada no botão da janela e pela etapa durante o
        fluxo. Isso evita aplicar no celular um item que já não responde.
        """
        parsed = urlsplit("http://" + str(raw).strip())
        if not parsed.hostname or not parsed.port or parsed.username is None or parsed.password is None:
            return False, "formato inválido (use usuário:senha@host:porta)"
        try:
            username = quote(unquote(parsed.username), safe="")
            password = quote(unquote(parsed.password), safe="")
            proxy_url = f"http://{username}:{password}@{parsed.hostname}:{parsed.port}"
            opener = build_opener(ProxyHandler({"http": proxy_url, "https": proxy_url}))
            request = Request("https://api.ipify.org?format=json", headers={"User-Agent": "iggen-proxy-test/1.0"})
            with opener.open(request, timeout=max(1, int(timeout_s))) as response:
                payload = json.loads(response.read().decode("utf-8"))
            shown_ip = str(payload.get("ip", "sem IP informado")) if isinstance(payload, dict) else str(payload)
            return True, f"OK — IP {shown_ip}"
        except Exception as error:
            return False, str(error)

    def add_proxy_action(self, action_ref: tuple[int, int] | None = None) -> None:
        """Cria ou edita uma lista sequencial de proxies desta etapa."""
        existing = None
        if action_ref is not None:
            existing = self.macros[self.flow_var.get()][action_ref[0]]["actions"][action_ref[1]]
        dialog = tk.Toplevel(self)
        dialog.title("Configurar proxies")
        dialog.geometry("700x560")
        dialog.minsize(620, 480)
        dialog.configure(bg="#171b26")
        dialog.transient(self); dialog.grab_set()
        ttk.Label(dialog, text="Um proxy por linha, no formato usuário:senha@host:porta.").pack(anchor="w", padx=18, pady=(18, 5))
        ttk.Label(dialog, text="Cada celular avança separadamente para o próximo proxy quando esta etapa voltar a executar.",
                  foreground="#9eafc5", wraplength=580).pack(anchor="w", padx=18, pady=(0, 9))
        editor = tk.Text(dialog, bg="#202737", fg="#edf3fb", insertbackground="#ffffff", relief="flat",
                         wrap="none", padx=8, pady=8, font=("Consolas", 10))
        editor.pack(fill="both", expand=True, padx=18, pady=(0, 12))
        previous = list(existing.proxy_urls or []) if existing else []
        if not previous and existing and existing.proxy_url:
            previous = [existing.proxy_url]
        editor.insert("1.0", "\n".join(previous))

        def save() -> None:
            values = [line.strip() for line in editor.get("1.0", "end").splitlines() if line.strip()]
            if not values:
                messagebox.showwarning("Configurar proxies", "Informe ao menos um proxy.", parent=dialog)
                return
            for raw in values:
                try:
                    parsed = urlsplit("http://" + raw)
                    if not parsed.hostname or not parsed.port or parsed.username is None or parsed.password is None:
                        raise ValueError
                except ValueError:
                    messagebox.showwarning("Configurar proxies", f"Proxy inválido:\n{raw}\n\nUse usuário:senha@host:porta.", parent=dialog)
                    return
            key = hashlib.sha1("\n".join(values).encode("utf-8")).hexdigest()[:12]
            if existing is not None and action_ref is not None:
                self.push_undo()
                existing.proxy_urls, existing.proxy_url, existing.proxy_key = values, values[0], key
                self.refresh_tree()
                item = f"a:{action_ref[0]}:{action_ref[1]}"
                if self.tree.exists(item):
                    self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
                self.save_macro(quiet=True)
                self.status.set(f"Lista de {len(values)} proxy(s) atualizada.")
            else:
                self._append_special_action(
                    Action("configure_proxy", delay_ms=400, proxy_urls=values, proxy_url=values[0], proxy_key=key,
                           proxy_type="http-tunnel", label="Configurar proxy"),
                    f"Etapa com {len(values)} proxy(s) adicionada."
                )
            dialog.destroy()

        buttons = ttk.Frame(dialog); buttons.pack(fill="x", padx=18, pady=(0, 18))
        ctk.CTkButton(buttons, text="Cancelar", command=dialog.destroy, width=90, height=30,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right")
        ctk.CTkButton(buttons, text="Salvar", command=save, width=90, height=30).pack(side="right", padx=(0, 8))
        ctk.CTkButton(buttons, text="Testar lista", width=112, height=30,
                      command=lambda: self._test_proxy_list([
                          line.strip() for line in editor.get("1.0", "end").splitlines() if line.strip()
                      ], dialog), fg_color="#2e7d5b", hover_color="#3b9670").pack(side="left")
        self._prepare_popup_window(dialog)

    def _proxydroid_apk_file(self) -> Path | None:
        preferred = APK_DIR / "ProxyDroidPlus.apk"
        if preferred.is_file():
            return preferred
        return next((path for path in APK_DIR.glob("*.apk") if "proxydroidplus" in path.name.casefold()), None)

    def _download_proxydroid_apk(self) -> Path:
        """Baixa uma cópia do APK quando ainda não existe no projeto."""
        APK_DIR.mkdir(parents=True, exist_ok=True)
        target = APK_DIR / "ProxyDroidPlus.apk"
        temporary = target.with_suffix(".apk.download")
        try:
            metadata_request = Request(PROXYDROID_RELEASE_API, headers={"Accept": "application/vnd.github+json", "User-Agent": "iggen/1.0"})
            with urlopen(metadata_request, timeout=30) as response:
                release = json.loads(response.read().decode("utf-8"))
            assets = release.get("assets", []) if isinstance(release, dict) else []
            download_url = next((str(asset.get("browser_download_url", "")) for asset in assets
                                 if str(asset.get("name", "")).casefold().endswith(".apk")), "")
            if not download_url:
                raise RuntimeError("o release compatível não possui um APK para baixar")
            request = Request(download_url, headers={"User-Agent": "iggen/1.0"})
            with urlopen(request, timeout=90) as response, temporary.open("wb") as output:
                while True:
                    chunk = response.read(256 * 1024)
                    if not chunk:
                        break
                    output.write(chunk)
            # APK é um arquivo ZIP. Evita salvar uma página de erro como se
            # fosse instalável, algo comum em serviços de download externos.
            if not temporary.is_file() or temporary.stat().st_size < 1_000_000:
                raise RuntimeError("o arquivo baixado está vazio ou incompleto")
            with temporary.open("rb") as downloaded:
                if downloaded.read(2) != b"PK":
                    raise RuntimeError("a fonte não retornou um APK válido")
            temporary.replace(target)
            return target
        except Exception as error:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass
            raise RuntimeError(f"Não foi possível baixar o ProxyDroid automaticamente: {error}") from error

    @staticmethod
    def _proxydroid_cli_available(adb: Adb) -> bool:
        try:
            package_info = adb.command("shell", "dumpsys", "package", "org.proxydroid", timeout=15)
        except RuntimeError:
            return False
        return "ProxyDroidCLI" in package_info

    def _sing_box_binary(self, abi: str) -> Path:
        """Obtém o binário oficial compatível com a arquitetura do telefone."""
        normalized_abi = {
            "arm64-v8a": "arm64",
            "armeabi-v7a": "armv7",
            "x86_64": "x86_64",
        }.get(abi.strip().casefold())
        if not normalized_abi:
            raise RuntimeError(f"Arquitetura do telefone não suportada para proxy root: {abi or 'não informada'}.")
        SING_BOX_DIR.mkdir(parents=True, exist_ok=True)
        target = SING_BOX_DIR / f"sing-box-android-{normalized_abi}"
        if target.is_file() and target.stat().st_size > 2_000_000:
            return target
        temporary = target.with_suffix(".tar.gz.download")
        try:
            request = Request(SING_BOX_RELEASE_API, headers={"Accept": "application/vnd.github+json", "User-Agent": "iggen/1.0"})
            with urlopen(request, timeout=30) as response:
                release = json.loads(response.read().decode("utf-8"))
            asset_name = f"android-{normalized_abi}.tar.gz"
            asset_url = next((str(asset.get("browser_download_url", "")) for asset in release.get("assets", [])
                              if str(asset.get("name", "")).casefold().endswith(asset_name)), "")
            if not asset_url:
                raise RuntimeError(f"O release atual não possui binário para {abi}.")
            with urlopen(Request(asset_url, headers={"User-Agent": "iggen/1.0"}), timeout=120) as response, temporary.open("wb") as output:
                shutil.copyfileobj(response, output)
            with tarfile.open(temporary, "r:gz") as archive:
                member = next((item for item in archive.getmembers()
                               if item.isfile() and Path(item.name).name == "sing-box"), None)
                if member is None:
                    raise RuntimeError("O pacote do sing-box não contém o binário esperado.")
                source = archive.extractfile(member)
                if source is None:
                    raise RuntimeError("Não foi possível extrair o binário do sing-box.")
                with source, target.open("wb") as output:
                    shutil.copyfileobj(source, output)
            if target.stat().st_size < 2_000_000:
                raise RuntimeError("O binário do sing-box foi baixado incompleto.")
            return target
        except Exception as error:
            target.unlink(missing_ok=True)
            raise RuntimeError(f"Não foi possível preparar o motor de proxy root: {error}") from error
        finally:
            temporary.unlink(missing_ok=True)

    @staticmethod
    def _sing_box_proxy_config(host: str, port: int, user: str, password: str, remote_dir: str) -> dict:
        """Configuração TCP global para um proxy HTTP autenticado."""
        return {
            "log": {"level": "info", "output": f"{remote_dir}/sing-box.log", "timestamp": True},
            "inbounds": [{
                "type": "tun", "tag": "iggen-tun", "interface_name": "iggen0",
                "address": ["172.19.0.1/30"], "auto_route": True,
                # Em alguns kernels Android, `system` cria a TUN mas não
                # consegue fazer poll do descritor. A pilha gVisor evita esse
                # problema e é a opção mais portável para execução root.
                "auto_redirect": True, "strict_route": True, "stack": "gvisor",
            }],
            "outbounds": [
                {"type": "http", "tag": "proxy", "server": host, "server_port": port,
                 "username": user, "password": password},
                {"type": "direct", "tag": "direct"},
            ],
            "route": {"final": "proxy"},
        }

    def _disable_root_proxy(self, adb: Adb, runtime_variables: RuntimeVariables) -> None:
        """Encerra apenas o proxy TCP e as regras criadas pelo iggen."""
        remote_dir = "/data/local/tmp/iggen-proxy"
        script = (
            f"if [ -f {remote_dir}/pid ]; then kill $(cat {remote_dir}/pid) 2>/dev/null; fi; "
            "iptables -t nat -D OUTPUT -j IGGEN_PROXY 2>/dev/null || true; "
            "iptables -t nat -F IGGEN_PROXY 2>/dev/null || true; iptables -t nat -X IGGEN_PROXY 2>/dev/null || true; "
            f"ip link delete iggen0 2>/dev/null || true; rm -f {remote_dir}/pid {remote_dir}/config.json {remote_dir}/redsocks.conf"
        )
        adb.command("shell", f"su -c {shlex.quote(script)}", timeout=25)
        runtime_variables.remove("PROXY_ROOT_ACTIVE", "PROXY_ROOT_HOST", "PROXY_ROOT_LABEL")

    def _ensure_redsocks_binary(self, adb: Adb) -> str:
        """Disponibiliza o redsocks sem abrir a interface do ProxyDroid."""
        source_binary = "/data/user/0/org.proxydroid/files/redsocks2"
        remote_dir = "/data/local/tmp/iggen-proxy"
        binary = f"{remote_dir}/redsocks2"
        available = adb.command("shell", f"su -c {shlex.quote(f'test -x {binary} && echo READY || true')}", timeout=15)
        if "READY" in available:
            return binary
        self.events.put(("status", "Preparando componente de proxy TCP no telefone…"))
        installed = bool(adb.command("shell", "pm", "path", "org.proxydroid", timeout=15).strip())
        if not installed:
            apk_path = self._proxydroid_apk_file() or self._download_proxydroid_apk()
            adb.command("install", "-r", str(apk_path), timeout=180)
        # Em alguns aparelhos o `su` não pode ler diretamente a pasta privada
        # do app. `run-as` lê o binário como o próprio ProxyDroid e o shell o
        # grava na área temporária, onde então o root pode executá-lo.
        adb.command("shell", f"mkdir -p {remote_dir}", timeout=15)
        adb.command("shell", f"run-as org.proxydroid cat files/redsocks2 > {binary}", timeout=25)
        prepare_script = f"chmod 700 {binary}; test -x {binary} && echo READY"
        available = adb.command("shell", f"su -c {shlex.quote(prepare_script)}", timeout=15)
        if "READY" not in available:
            raise RuntimeError("Não foi possível preparar o componente TCP do proxy neste telefone.")
        return binary

    @staticmethod
    def _redsocks_config(host: str, port: int, user: str, password: str) -> str:
        def escape(value: str) -> str:
            return value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "")
        return (
            "base { log_debug = off; log_info = on; log = \"stderr\"; daemon = off; redirector = iptables; }\n"
            "redsocks { bind = \"127.0.0.1:8124\"; "
            # A versão embarcada no telefone usa ``relay`` como endereço
            # completo e não implementa a chave ``relay_port``.
            f"relay = \"{escape(host)}:{int(port)}\"; type = http-connect; "
            f"login = \"{escape(user)}\"; password = \"{escape(password)}\"; }}\n"
        )

    def _configure_proxy(self, adb: Adb, action: Action, runtime_variables: RuntimeVariables) -> str:
        """Configura e conecta o ProxyDroid no aparelho da etapa atual."""
        proxy_values = [str(value).strip() for value in (action.proxy_urls or []) if str(value).strip()]
        if not proxy_values and action.proxy_url:
            proxy_values = [str(action.proxy_url).strip()]
        if not proxy_values:
            raise RuntimeError("Esta etapa não possui proxies configurados.")
        key = action.proxy_key or hashlib.sha1("\n".join(proxy_values).encode("utf-8")).hexdigest()[:12]
        index_key = f"PROXY_INDEX_{key}"
        try:
            index = max(0, int(runtime_variables.get(index_key, 0))) % len(proxy_values)
        except (TypeError, ValueError):
            index = 0
        # Testa primeiro o proxy que seria usado nesta rodada. Caso ele não
        # responda, avança pela lista antes de alterar a rede do telefone.
        # Cada telefone mantém seu próprio índice em RuntimeVariables.
        raw = ""
        selected_index = index
        test_failures: list[str] = []
        for offset in range(len(proxy_values)):
            candidate_index = (index + offset) % len(proxy_values)
            candidate = proxy_values[candidate_index]
            ok, detail = self._test_proxy_connection(candidate)
            candidate_parsed = urlsplit("http://" + candidate)
            candidate_label = f"{candidate_parsed.hostname or 'proxy'}:{candidate_parsed.port or '--'}"
            if ok:
                raw, selected_index = candidate, candidate_index
                self.events.put(("status", f"Proxy {candidate_label} testado antes de configurar: {detail}."))
                break
            test_failures.append(f"{candidate_label}: {detail}")
            self.events.put(("status", f"Proxy {candidate_label} não respondeu; tentando o próximo da lista."))
        if not raw:
            runtime_variables.set(index_key, (index + 1) % len(proxy_values))
            details = " | ".join(test_failures[-3:])
            raise RuntimeError(f"Nenhum proxy da lista respondeu ao teste.{(' ' + details) if details else ''}")
        parsed = urlsplit("http://" + raw)
        if not parsed.hostname or not parsed.port or parsed.username is None or parsed.password is None:
            raise RuntimeError("Proxy inválido. Use usuário:senha@host:porta.")
        # Proxy HTTP autenticado transporta TCP, não UDP. Usamos redsocks com
        # iptables diretamente: evita a interface TUN que falha em alguns
        # kernels Android e não depende da tela do ProxyDroid.
        redsocks_binary = self._ensure_redsocks_binary(adb)
        remote_dir = "/data/local/tmp/iggen-proxy"
        remote_config = f"{remote_dir}/redsocks.conf"
        config = self._redsocks_config(parsed.hostname, parsed.port, unquote(parsed.username), unquote(parsed.password))
        local_config = RUNTIME_DIR / re.sub(r"[^A-Za-z0-9_.-]", "_", str(adb.serial or "telefone")) / "redsocks.conf"
        local_config.parent.mkdir(parents=True, exist_ok=True)
        local_config.write_text(config, encoding="utf-8")
        try:
            adb.command("shell", "mkdir", "-p", remote_dir, timeout=15)
            adb.command("push", str(local_config), remote_config, timeout=30)
            rules_script = (
                "iptables -t nat -D OUTPUT -j IGGEN_PROXY 2>/dev/null || true; "
                "iptables -t nat -N IGGEN_PROXY 2>/dev/null || true; iptables -t nat -F IGGEN_PROXY; "
                "iptables -t nat -A IGGEN_PROXY -m owner --uid-owner 0 -j RETURN; "
                "iptables -t nat -A IGGEN_PROXY -d 127.0.0.0/8 -j RETURN; "
                "iptables -t nat -A IGGEN_PROXY -p tcp -j REDIRECT --to-ports 8124; "
                "iptables -t nat -A OUTPUT -j IGGEN_PROXY"
            )
            start_script = (
                f"if [ -f {remote_dir}/pid ]; then kill $(cat {remote_dir}/pid) 2>/dev/null; fi; "
                f"chmod 600 {remote_config}; nohup {redsocks_binary} -c {remote_config} > {remote_dir}/redsocks.log 2>&1 & "
                f"echo $! > {remote_dir}/pid; {rules_script}"
            )
            adb.command("shell", f"su -c {shlex.quote(start_script)}", timeout=30)
            if self.run_stop_event.wait(2):
                return raw
            health_script = f"test -s {remote_dir}/pid && kill -0 $(cat {remote_dir}/pid) && iptables -t nat -C OUTPUT -j IGGEN_PROXY"
            try:
                adb.command("shell", f"su -c {shlex.quote(health_script)}", timeout=15)
            except RuntimeError as exc:
                log_script = f"tail -n 8 {remote_dir}/redsocks.log 2>/dev/null || true"
                detail = adb.command("shell", f"su -c {shlex.quote(log_script)}", timeout=10).strip()
                self._disable_root_proxy(adb, runtime_variables)
                if detail:
                    raise RuntimeError(f"O componente do proxy não iniciou: {detail}") from exc
                raise RuntimeError("O componente do proxy não iniciou neste telefone.") from exc
        finally:
            local_config.unlink(missing_ok=True)
        runtime_variables.set("PROXY_ROOT_ACTIVE", True)
        runtime_variables.set("PROXY_ROOT_HOST", parsed.hostname)
        runtime_variables.set("PROXY_ROOT_LABEL", f"{parsed.hostname}:{parsed.port}")
        self.events.put(("status", f"Proxy root TCP ativo no telefone atual ({parsed.hostname}:{parsed.port})."))
        runtime_variables.set(index_key, (selected_index + 1) % len(proxy_values))
        return raw

        serial = str(adb.serial or "telefone")
        abi = adb.command("shell", "getprop", "ro.product.cpu.abi", timeout=12).strip()
        self.events.put(("status", f"Preparando proxy root ({abi}) no telefone atual…"))
        binary = self._sing_box_binary(abi)
        remote_dir = "/data/local/tmp/iggen-proxy"
        remote_binary = f"{remote_dir}/sing-box"
        remote_config = f"{remote_dir}/config.json"
        local_config = RUNTIME_DIR / re.sub(r"[^A-Za-z0-9_.-]", "_", serial) / "sing-box-config.json"
        local_config.parent.mkdir(parents=True, exist_ok=True)
        local_config.write_text(json.dumps(
            self._sing_box_proxy_config(parsed.hostname, parsed.port, unquote(parsed.username), unquote(parsed.password), remote_dir),
            ensure_ascii=False,
        ), encoding="utf-8")
        try:
            adb.command("shell", "mkdir", "-p", remote_dir, timeout=15)
            adb.command("push", str(binary), remote_binary, timeout=120)
            adb.command("push", str(local_config), remote_config, timeout=30)
            check_script = f"chmod 700 {remote_binary}; chmod 600 {remote_config}; {remote_binary} check -c {remote_config}"
            # `adb shell` junta os argumentos novamente no Android. Enviar o
            # script como uma única expressão protegida evita quebrar `if …
            # then` e expansões como `$(cat pid)` no caminho.
            adb.command("shell", f"su -c {shlex.quote(check_script)}", timeout=35)
            start_script = (
                f"if [ -f {remote_dir}/pid ]; then kill $(cat {remote_dir}/pid) 2>/dev/null; fi; "
                f"nohup {remote_binary} run -c {remote_config} > {remote_dir}/sing-box.log 2>&1 & "
                f"echo $! > {remote_dir}/pid"
            )
            adb.command("shell", f"su -c {shlex.quote(start_script)}", timeout=25)
            if self.run_stop_event.wait(2):
                return raw
            health_script = (
                f"if test -s {remote_dir}/pid && kill -0 $(cat {remote_dir}/pid) "
                f"&& ip link show iggen0 >/dev/null 2>&1; then echo ACTIVE; else echo INACTIVE; fi"
            )
            health = adb.command("shell", f"su -c {shlex.quote(health_script)}", timeout=15).strip()
            if health != "ACTIVE":
                log_script = f"tail -n 12 {remote_dir}/sing-box.log 2>/dev/null || true"
                detail = adb.command("shell", f"su -c {shlex.quote(log_script)}", timeout=15).strip()
                raise RuntimeError(f"O proxy root não ficou ativo.{(' Detalhe: ' + detail) if detail else ''}")
        finally:
            local_config.unlink(missing_ok=True)
        runtime_variables.set("PROXY_ROOT_ACTIVE", True)
        runtime_variables.set("PROXY_ROOT_HOST", parsed.hostname)
        self.events.put(("status", f"Proxy root ativo no telefone atual ({parsed.hostname}:{parsed.port})."))
        runtime_variables.set(index_key, (index + 1) % len(proxy_values))
        return raw

        receiver = "org.proxydroid/.ProxyDroidCLI"
        try:
            installed = bool(adb.command("shell", "pm", "path", "org.proxydroid", timeout=12).strip())
        except RuntimeError:
            installed = False
        if installed and not self._proxydroid_cli_available(adb):
            # A edição comum usa o mesmo pacote, mas não aceita os broadcasts
            # necessários. Ela precisa ser substituída para a automação funcionar.
            self.events.put(("status", "Substituindo o ProxyDroid comum pela versão compatível com automação…"))
            adb.command("uninstall", "org.proxydroid", timeout=40)
            installed = False
        if not installed:
            apk_path = self._proxydroid_apk_file()
            if not apk_path:
                self.events.put(("status", "Baixando ProxyDroid para instalar no telefone…"))
                apk_path = self._download_proxydroid_apk()
            adb.command("install", "-r", str(apk_path), timeout=180)
        # A versão compatível cria o perfil inicial quando é aberta uma vez;
        # só depois disso o receiver de configuração fica disponível.
        adb.launch_package("org.proxydroid", timeout=20)
        if self.run_stop_event.wait(2):
            return raw
        def configure(*values: str) -> None:
            adb.command("shell", "am", "broadcast", "-n", receiver,
                        "-a", "org.proxydroid.PROFILE_CONFIGURE", *values, timeout=15)
        configure("--es", "proxyType", action.proxy_type or "http-tunnel")
        configure("--es", "host", parsed.hostname)
        configure("--ei", "port", str(parsed.port))
        configure("--ez", "isAuth", "true")
        configure("--es", "user", unquote(parsed.username))
        configure("--es", "password", unquote(parsed.password))
        configure("--ez", "isGlobalProxy", "true")
        # No Android 15, o receiver do ProxyDroid tenta iniciar o serviço em
        # segundo plano e o sistema devolve FAILURE antes de o código de root
        # sequer ser executado. Iniciar o foreground service diretamente pelo
        # ADB evita essa limitação e entrega a mesma configuração ao serviço.
        adb.command(
            "shell", "am", "start-foreground-service", "-n", "org.proxydroid/.ProxyDroidService",
            "--es", "host", parsed.hostname,
            "--es", "user", unquote(parsed.username),
            "--es", "bypassAddrs", "",
            "--es", "password", unquote(parsed.password),
            "--es", "domain", "",
            "--es", "proxyType", action.proxy_type or "http-tunnel",
            "--ez", "isGlobalProxy", "true",
            "--ez", "isBypassApps", "false",
            "--ez", "isAuth", "true",
            "--ez", "isNTLM", "false",
            "--ez", "isPAC", "false",
            "--ei", "port", str(parsed.port),
            timeout=20,
        )
        runtime_variables.set(index_key, (index + 1) % len(proxy_values))
        return raw

