    def add_schedule_divider_action(self) -> None:
        """Insere um divisor de horário entre grupos, sem alterar a seleção."""
        name = simpledialog.askstring(
            "Divisão de horários", "Nome do período (ex.: MANHÃ, TARDE ou NOITE):", parent=self
        )
        if name is None or not name.strip():
            return
        time_min = simpledialog.askstring(
            "Divisão de horários", "Início do intervalo (HH:MM):", initialvalue="08:00", parent=self,
        )
        if time_min is None:
            return
        time_max = simpledialog.askstring(
            "Divisão de horários", "Fim do intervalo (HH:MM):", initialvalue="10:00", parent=self,
        )
        if time_max is None:
            return
        try:
            start_minutes = self._schedule_minutes(time_min)
            end_minutes = self._schedule_minutes(time_max)
        except ValueError:
            messagebox.showwarning("Divisão de horários", "Use o formato HH:MM, por exemplo 08:00.", parent=self)
            return
        if end_minutes <= start_minutes:
            messagebox.showwarning("Divisão de horários", "O fim do intervalo deve ser depois do início.", parent=self)
            return
        normalized_start = f"{start_minutes // 60:02d}:{start_minutes % 60:02d}"
        normalized_end = f"{end_minutes // 60:02d}:{end_minutes % 60:02d}"
        slot_id = uuid.uuid4().hex
        divider = Action(
            "schedule_divider", delay_ms=0, label=name.strip(), text_value=name.strip(),
            schedule_time_min=normalized_start, schedule_time_max=normalized_end,
            schedule_slot_id=slot_id,
        )
        closing_divider = Action(
            "schedule_divider_end", delay_ms=0, label=name.strip(), text_value=name.strip(),
            schedule_time_min=normalized_start, schedule_time_max=normalized_end,
            schedule_slot_id=slot_id,
        )
        groups = self.macros[self.flow_var.get()]
        selected_groups = []
        for item in self.tree.selection():
            parts = item.split(":")
            if parts[0] == "g" and len(parts) == 2:
                try:
                    index = int(parts[1])
                except ValueError:
                    continue
                if 0 <= index < len(groups):
                    selected_groups.append(index)

        # As réguas delimitam visualmente o período: uma antes da seleção e
        # outra depois dela. Só a primeira controla o horário de execução.
        insert_at = min(selected_groups) if selected_groups else len(groups)
        closing_at = max(selected_groups) + 2 if selected_groups else insert_at + 1
        self.push_undo()
        groups.insert(insert_at, {
            "name": name.strip(),
            "enabled": True,
            "schedule_divider_group": True,
            "schedule_divider_edge": "start",
            "actions": [divider],
        })
        groups.insert(closing_at, {
            "name": name.strip(),
            "enabled": True,
            "schedule_divider_group": True,
            "schedule_divider_edge": "end",
            "actions": [closing_divider],
        })
        item = f"g:{insert_at}"
        self._tree_open_after_refresh = getattr(self, "_tree_open_after_refresh", set())
        self.refresh_tree()
        self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set(
            f"Divisões adicionadas antes e depois da seleção: {normalized_start}–{normalized_end}. "
            "Os grupos foram preservados."
        )

    @staticmethod
    def _schedule_minutes(value: str) -> int:
        """Converte HH:MM e rejeita horários ambíguos antes de salvar."""
        match = re.fullmatch(r"\s*(\d{1,2}):(\d{2})\s*", str(value or ""))
        if not match:
            raise ValueError("horário inválido")
        hour, minute = int(match.group(1)), int(match.group(2))
        if not 0 <= hour <= 23 or not 0 <= minute <= 59:
            raise ValueError("horário inválido")
        return hour * 60 + minute

    def configure_schedule_divider(self, action: Action) -> None:
        """Edita a janela do divisor sem trocar seu id persistente."""
        name = simpledialog.askstring("Divisão de horários", "Nome do período:", initialvalue=action.text_value or action.label or "", parent=self)
        if name is None or not name.strip():
            return
        start_value = action.schedule_time_min or "08:00"
        end_value = action.schedule_time_max or "10:00"
        time_min = simpledialog.askstring("Divisão de horários", "Início do intervalo (HH:MM):", initialvalue=start_value, parent=self)
        if time_min is None:
            return
        time_max = simpledialog.askstring("Divisão de horários", "Fim do intervalo (HH:MM):", initialvalue=end_value, parent=self)
        if time_max is None:
            return
        try:
            start_minutes, end_minutes = self._schedule_minutes(time_min), self._schedule_minutes(time_max)
        except ValueError:
            messagebox.showwarning("Divisão de horários", "Use o formato HH:MM, por exemplo 08:00.", parent=self)
            return
        if end_minutes <= start_minutes:
            messagebox.showwarning("Divisão de horários", "O fim do intervalo deve ser depois do início.", parent=self)
            return
        new_min = f"{start_minutes // 60:02d}:{start_minutes % 60:02d}"
        new_max = f"{end_minutes // 60:02d}:{end_minutes % 60:02d}"
        # As duas faixas do mesmo período compartilham o mesmo id. Ao editar
        # qualquer uma delas, mantenha início e fim visualmente sincronizados.
        linked_id = action.schedule_slot_id
        updated = False
        for group in self.macros[self.flow_var.get()]:
            for candidate_index, candidate in enumerate(group.get("actions", [])):
                if isinstance(candidate, dict):
                    candidate = Action(**candidate)
                    group["actions"][candidate_index] = candidate
                if (candidate is action or (linked_id and candidate.schedule_slot_id == linked_id)):
                    candidate.label = candidate.text_value = name.strip()
                    candidate.schedule_time_min = new_min
                    candidate.schedule_time_max = new_max
                    updated = True
        if not updated:
            action.label = action.text_value = name.strip()
            action.schedule_time_min = new_min
            action.schedule_time_max = new_max
        self.save_macro(quiet=True)
        self.refresh_tree()
        self.status.set("Divisão de horários atualizada.")

